function menuItems(){if(APP_MODE!=="admin")return MENU_USER.map(([g,items])=>[g,items.filter(i=>i[2](ME))]).filter(g=>g[1].length);return modGroups(curMod())}
function curMod(){const vm=visibleMods();if(!MOD){try{MOD=localStorage.getItem(SKEY+"_m")||""}catch(e){}}let mo=vm.find(x=>x.k===MOD)||vm.find(x=>modGroups(x).some(g=>g[1].some(i=>i[0]===PAGE)))||vm[0];const has=x=>modGroups(x).some(g=>g[1].some(i=>i[0]===PAGE));if(PAGE&&!has(mo)){const o=vm.find(has);if(o)mo=o}MOD=mo.k;try{localStorage.setItem(SKEY+"_m",MOD)}catch(e){}return mo}

