  m.querySelectorAll("[data-hq-h]").forEach(x=>x.onchange=()=>{DB.mutate(ME.name,`điều chỉnh giữa tháng: hướng ${sk(x.dataset.hqH).n} → ${x.value}`,dt=>dt.products.find(p=>p.k===x.dataset.hqH).huong=x.value);toast("Đã điều chỉnh, ghi vào nhật ký");renderMain()});
  m.querySelectorAll("[data-hq-g]").forEach(x=>x.onchange=()=>{DB.mutate(ME.name,`điều chỉnh giữa tháng: mục tiêu ${sk(x.dataset.hqG).n} → ${x.value} triệu`,dt=>dt.goals[x.dataset.hqG].gmv=(+x.value||0)*1e6);toast("Đã điều chỉnh mục tiêu");renderMain()});
  if($("#go-live"))$("#go-live").onclick=()=>{if(!confirm("Chuyển sang dữ liệu thật: xóa toàn bộ tiến độ mẫu tháng 10 (thẻ đã quay, đã đăng, doanh thu, báo cáo tuần mẫu…), giữ nguyên kế hoạch, pillar, tuyến, danh sách thẻ. Tiếp tục?"))return;DB.mutate(ME.name,"chuyển sang dữ liệu thật tháng "+MONTH.mon,dt=>goLive(dt));toast("Đã chuyển. Tháng 10 bắt đầu từ hôm nay");render()};
  m.querySelectorAll(".prodrow .kpi").forEach(x=>x.onclick=()=>{PAGE="congviec";render();scrollTo(0,0)});
