function cvList(u){
  const d=D(),C=d.cards,td=d.settings.today,mine=c=>["admin","lead"].includes(u.role)||c.nguoi===u.id;
  const L=[];const add=(key,t,lvl,items,act)=>{if(items.length)L.push({key,t,lvl,items,act})};
  if(can(u,"viec.duyet")){add("dkb","Kịch bản chờ duyệt","blu",C.filter(c=>c.step==="dkb"),"card");add("dvd","Video chờ duyệt + CEO check","blu",C.filter(c=>c.step==="dvd"),"card")}
  if(can(u,"viec.giao"))add("cg","Thẻ 7 ngày tới chưa giao","red",C.filter(c=>c.step==="cg"&&c.day<=td+7),"assign");
  add("tre","Trễ hạn","red",C.filter(c=>isLate(c)&&mine(c)),"card");
  add("bitra","Bị trả lại, cần sửa","amb",C.filter(c=>["kb","quay"].includes(c.step)&&(c.gopy||[]).length&&mine(c)),"card");
  add("id","Đã đăng nhưng thiếu ID / link bài","red",C.filter(c=>c.step==="xong"&&mine(c)&&(chOf(c.kenh).needId?!c.tiktokId:!c.linkDang)),"card");
  add("sap","Đăng trong 2 ngày tới, chưa có kịch bản","amb",C.filter(c=>c.step==="kb"&&c.day<=td+2&&c.day>=td&&mine(c)),"card");
  if(can(u,"win.sua"))add("win","Video win chưa có kế hoạch nhân bản","pnk",winners().filter(w=>!d.winPlans.some(p=>p.src===w.key)).slice(0,10),"win");
  if(can(u,"order.xem"))add("order","Order sắp tới hạn / trễ","amb",d.orders.filter(o=>o.trangThai!=="Xong"&&o.han<=td+2&&(["admin","lead"].includes(u.role)||o.giao===u.id||o.nguoiOrder===u.id)),"order");
  if(can(u,"research.duyet"))add("rs","Research chờ kiểm / duyệt","blu",d.research.filter(r=>["Chờ kiểm tra","Đã kiểm"].includes(r.status)),"research");
  if(u.role!=="admin"&&can(u,"research.sua"))add("q","Câu hỏi research được giao","blu",d.questions.filter(q=>q.to===u.id&&q.status!=="Xong"),"research");
  const lastTT=d.imports.find(i=>i.loai==="TikTok"),lastAds=d.imports.find(i=>i.loai==="Ads Facebook"),needW=weekOf(td)-1;
  if(can(u,"baocao.tiktok")&&(!lastTT||lastTT.tuan<needW))add("bctt",`Chưa nhập báo cáo TikTok tuần ${needW}`,"red",[{t:"Nhập file Video Performance List tuần "+needW}],"baocao");
  if(can(u,"baocao.ads")&&(!lastAds||lastAds.tuan<needW))add("bcads",`Chưa nhập báo cáo Ads Facebook tuần ${needW}`,"red",[{t:"Nhập file Ads tuần "+needW}],"baocao");
  if(can(u,"kehoach.duyet"))add("plan","Bước kế hoạch chờ duyệt","pnk",Object.entries(d.plan.steps).filter(([,v])=>v.s==="review").map(([k,v])=>({t:"Bước "+k+": "+(v.note||"")})),"kehoach");
  return {L,total:sum(L,x=>x.items.length)};
}
function pCV(m){
  const {L,total}=cvList(ME);
  m.innerHTML=H("Cần duyệt",total?`${total} việc`:"Không còn việc tồn")+`<div class="cv-grid">${L.map(g=>`<section class="card cv cv-${g.lvl}"><div class="card-h"><h2>${g.t}</h2>${pill(g.items.length,g.lvl)}</div><div class="cv-list">${g.items.slice(0,12).map(it=>cvItem(g,it)).join("")}${g.items.length>12?`<div class="hint">+${g.items.length-12} việc nữa</div>`:""}</div></section>`).join("")||`<section class="card"><p class="empty">Mọi việc đã xong.</p></section>`}</div>`;
}
function cvItem(g,it){
  if(g.act==="card"||g.act==="assign")return `<div class="cvi" data-card="${it.id}">${swatch(it.sku)}<div><b>${esc(it.hookText||it.yTuong)}</b><small>${it.id} · ${esc(chOf(it.kenh).short)} · ${it.nguoi?esc(userName(it.nguoi)):"chưa giao"} · ${dd(it.day)}</small></div>${g.act==="assign"?`<select data-assign="${it.id}">${opt(userOpts("Giao cho…"),"")}</select>`:stepPill(it)}</div>`;
  if(g.act==="win")return `<div class="cvi">${swatch(it.sku)}<div><b>${esc(it.ten)}</b><small>${nf(it.don)} đơn · ${money(it.gmv)}</small></div><button class="btn sm" data-go="win" data-sub="rank">Lên kế hoạch</button></div>`;
  if(g.act==="order")return `<div class="cvi"><div><b>${it.ma} · ${esc(sk(it.sku).n)}</b><small>${esc(it.muc)} · hạn ${dd(it.han)}</small></div><button class="btn sm" data-go="order">Mở</button></div>`;
  if(g.act==="research")return `<div class="cvi"><div><b>${esc(it.bangChung||it.q)}</b><small>${esc(sk(it.sku).n)}${it.status?" · "+it.status:""}</small></div><button class="btn sm" data-go="research">Mở</button></div>`;
  return `<div class="cvi"><div><b>${esc(it.t)}</b></div><button class="btn sm" data-go="${g.act}">Mở</button></div>`;
}

