let LF={sku:"",nguoi:""};
function pLich(m){
  const tab=SUB.lich||"cal";const tabs=[["cal","Lịch tháng"],["pillar","Pillar & tuyến"]].concat(CHANNELS.map(c=>[c.k,c.k]));
  m.innerHTML=H("Lịch content")+`<div class="tabs">${tabs.map(([k,t])=>`<button data-sub="${esc(k)}" class="${k===tab?"on":""}">${t}${CHANNELS.some(c=>c.k===k)?`<span>${D().cards.filter(c=>c.kenh===k).length}</span>`:""}</button>`).join("")}</div>
   ${tab!=="pillar"?`<div class="filters"><select id="lf-s">${opt([["","Mọi sản phẩm"]].concat(skOpts()),LF.sku)}</select><select id="lf-n">${opt([["","Mọi người"]].concat(workers().map(u=>[u.id,u.name])),LF.nguoi)}</select>${can(ME,"lich.sua_tat_ca")&&tab!=="cal"?`<span class="sp"></span><button class="btn pri" id="addc">+ Thêm nội dung</button>`:""}</div>`:""}<div id="lb"></div>`;
  if($("#lf-s")){$("#lf-s").onchange=e=>{LF.sku=e.target.value;renderMain()};$("#lf-n").onchange=e=>{LF.nguoi=e.target.value;renderMain()}}
  if($("#addc"))$("#addc").onclick=()=>{let id;DB.mutate(ME.name,"thêm nội dung "+tab,dt=>{const c=newCard(dt,{sku:"BT",kenh:tab,day:dt.settings.today+3});dt.cards.push(c);id=c.id});renderMain();openCard(id)};
  const C=D().cards.filter(c=>(!LF.sku||c.sku===LF.sku)&&(!LF.nguoi||c.nguoi===LF.nguoi));
  if(tab==="cal")lichCal($("#lb"),C);else if(tab==="pillar")lichPillar($("#lb"));else lichKenh($("#lb"),C.filter(c=>c.kenh===tab),tab);
}
function lichCal(b,C){
  const td=D().settings.today,cut=D().settings.cutoff;const cells=[];for(let i=0;i<dow(1);i++)cells.push(0);for(let d=1;d<=MONTH.ndays;d++)cells.push(d);while(cells.length%7)cells.push(0);
  const ev=d=>d>=14&&d<=21?"SN Ailla":d===10?"10/10":d===20?"20/10":"";
  b.innerHTML=`<section class="card"><div class="calwrap"><div class="cal">${["Thứ 2","Thứ 3","Thứ 4","Thứ 5","Thứ 6","Thứ 7","CN"].map(x=>`<div class="hd">${x}</div>`).join("")}
  ${cells.map(d=>{if(!d)return `<div class="day out"></div>`;const it=C.filter(c=>c.day===d);const e=ev(d);return `<div class="day${d<td?" past":""}${d===td?" today":""}"><div class="dn"><b>${d}</b>${e?pill(e,"pnk"):""}<span>${it.length}</span></div>${it.slice(0,5).map(c=>`<div class="it${c.step==="cg"?" cg":""}" data-card="${c.id}" style="border-color:${sk(c.sku).c}"><span>${esc((c.hookText||c.yTuong).slice(0,44))}</span><small>${chOf(c.kenh).short} · ${c.nguoi?esc(userName(c.nguoi)):"chưa giao"}${c.step==="xong"?" · ✓":""}</small></div>`).join("")}${it.length>5?`<div class="more">+${it.length-5}</div>`:""}<div class="res">${d<=cut?`<b>${sum(it,c=>c.don)}</b> đơn · ${money(sum(it,c=>c.gmv))}`:"&nbsp;"}</div></div>`}).join("")}</div></div>
  <div class="legend">${prods().map(p=>`<span>${swatch(p.k)}${esc(p.n)}</span>`).join("")}<span><i class="sw dash"></i>chưa giao</span></div></section>`;
}
function lichPillar(b){
  const d=D(),ed=can(ME,"kehoach.sua"),C=d.cards;
  const inp=(i,f,v,cls="")=>`<input class="${cls}" data-pl="${i}" data-f="${f}" value="${esc(v)}">`;
  const area=(i,f,v)=>`<textarea rows="2" data-pl="${i}" data-f="${f}">${esc(v)}</textarea>`;
  const tinp=(i,f,v,cls="")=>`<input class="${cls}" data-tu="${i}" data-f="${f}" value="${esc(v)}">`;
  b.innerHTML=`${ed?"":`<div class="note">Bạn chỉ được xem. Muốn sửa pillar và tuyến cần quyền "Sửa kế hoạch" (chị cấp ở Nhân sự & phân quyền).</div>`}
  <section class="card"><div class="card-h"><h2>Sản phẩm trong kế hoạch tháng ${MONTH.mon}</h2><span class="hint">${prods().length} sản phẩm</span></div><div class="chips2">${prods().map(p=>`<span class="pchip">${swatch(p.k)}${esc(p.n)} ${pill(p.huong,p.huong==="Đẩy mạnh"?"pnk":p.huong==="Đẩy nhẹ"||p.huong==="Test"?"amb":"gry")}<small>${chOf(p.kenh).short} · ${d.tuyen.filter(t=>t.sku===p.k).length} tuyến</small>${ed?`<button class="lnk danger" data-rmp="${p.k}" title="Bỏ khỏi kế hoạch">✕</button>`:""}</span>`).join("")}</div>${addProdForm(ed)}<p class="hint">Thêm sản phẩm xong → thêm tuyến cho sản phẩm đó ở bảng Tuyến bên dưới → bấm Phát hành để có thẻ việc.</p></section>
  <section class="card"><div class="card-h"><h2>Pillar tháng</h2><span class="hint">PILLAR_THANG${ed?" · bấm vào ô để sửa, sửa xong bấm ra ngoài là lưu":""}</span></div>
  <div class="tbl edit"><table><thead><tr><th>Mã</th><th>Sản phẩm</th><th>Kênh</th><th>Vai trò</th><th>Mục tiêu kinh doanh</th><th class="n">Sản lượng KH</th><th>Định dạng</th><th>Big idea</th><th>Phụ trách</th><th>Ghi chú</th><th class="n">Đã triển khai</th><th class="n">Còn thiếu</th>${ed?"<th></th>":""}</tr></thead><tbody>
  ${d.pillars.map((p,i)=>{const done=C.filter(c=>c.kenh===p.kenh&&c.step==="xong"&&(p.kenh!=="TikTok chính"||c.sku===p.sku)).length;
    return ed?`<tr><td>${inp(i,"ma",p.ma,"mono s2")}</td><td><select data-pl="${i}" data-f="sku">${opt(skOpts(),p.sku)}</select></td><td><select data-pl="${i}" data-f="kenh">${opt(CHANNELS.map(c=>c.k),p.kenh)}</select></td><td>${area(i,"vaiTro",p.vaiTro)}</td><td>${area(i,"mucTieu",p.mucTieu)}</td><td class="n">${inp(i,"kh",p.kh,"num s")}</td><td>${inp(i,"dinhDang",p.dinhDang)}</td><td>${area(i,"idea",p.idea)}</td><td><select data-pl="${i}" data-f="nguoi">${opt(userOpts(),p.nguoi)}</select></td><td>${area(i,"ghiChu",p.ghiChu||"")}</td><td class="n">${done}</td><td class="n">${Math.max(0,p.kh-done)}</td><td><button class="btn sm danger" data-pdel="${i}">Xóa</button></td></tr>`
    :`<tr><td class="mono">${p.ma}</td><td>${swatch(p.sku)}${sk(p.sku).n}</td><td>${p.kenh}</td><td>${esc(p.vaiTro)}</td><td>${esc(p.mucTieu)}</td><td class="n">${p.kh}</td><td>${esc(p.dinhDang)}</td><td>${esc(p.idea)}</td><td>${esc(userName(p.nguoi))}</td><td>${esc(p.ghiChu||"")}</td><td class="n">${done}</td><td class="n">${Math.max(0,p.kh-done)}</td></tr>`}).join("")}
  ${ed?"":""}</tbody></table></div>${ed?`<div class="acts"><button class="btn" id="padd">+ Thêm pillar</button></div>`:""}</section>
  <section class="card"><div class="card-h"><h2>Tuyến tháng</h2><span class="hint">TUYEN_THANG · mỗi tuyến sinh thẻ khi phát hành</span>${ed?`<span class="sp"></span><button class="btn pri sm" id="pub2">Phát hành thẻ còn thiếu</button>`:""}</div>
  <div class="tbl edit"><table><thead><tr><th>Mã tuyến</th><th>Kênh</th><th>Sản phẩm</th><th>Tuyến content</th><th>Vai trò</th><th class="n">Số lượng KH</th><th class="n">Đã có thẻ</th><th class="n">Đã đăng</th><th class="n">Còn thiếu</th><th>Phụ trách</th><th>Kiểm chứng</th><th>Mã insight</th><th>Ghi chú</th>${ed?"<th></th>":""}</tr></thead><tbody>
  ${d.tuyen.map((t,i)=>{const cs=C.filter(c=>c.maTuyen===t.ma),dn=cs.filter(c=>c.step==="xong").length;
    return ed?`<tr><td class="mono">${t.ma}</td><td><select data-tu="${i}" data-f="kenh">${opt(CHANNELS.map(c=>c.k),t.kenh)}</select></td><td><select data-tu="${i}" data-f="sku">${opt(skOpts(),t.sku)}</select></td><td><select data-tu="${i}" data-f="tuyen">${opt(LISTS.tuyen.concat(LISTS.tuyen.includes(t.tuyen)?[]:[t.tuyen]),t.tuyen)}</select></td><td>${tinp(i,"vaiTro",t.vaiTro)}</td><td class="n">${tinp(i,"kh",t.kh,"num s")}</td><td class="n">${cs.length}</td><td class="n">${dn}</td><td class="n">${Math.max(0,t.kh-dn)}</td><td><select data-tu="${i}" data-f="nguoi">${opt(userOpts(),t.nguoi)}</select></td><td><select data-tu="${i}" data-f="kiemChung">${opt(["Giả thuyết","Có bằng chứng"],t.kiemChung)}</select></td><td><select data-tu="${i}" data-f="maInsight">${opt([["",""]].concat(d.insights.map(x=>[x.ma,x.ma])),t.maInsight)}</select></td><td>${tinp(i,"ghiChu",t.ghiChu||"")}</td><td>${cs.length?"":`<button class="btn sm danger" data-tdel="${i}">Xóa</button>`}</td></tr>`
    :`<tr><td class="mono">${t.ma}</td><td>${chOf(t.kenh).short}</td><td>${swatch(t.sku)}${sk(t.sku).n}</td><td>${esc(t.tuyen)}</td><td>${esc(t.vaiTro)}</td><td class="n">${t.kh}</td><td class="n">${cs.length}</td><td class="n">${dn}</td><td class="n">${Math.max(0,t.kh-dn)}</td><td>${esc(userName(t.nguoi))}</td><td>${pill(t.kiemChung,t.kiemChung==="Có bằng chứng"?"grn":"amb")}</td><td class="mono">${esc(t.maInsight)}</td><td>${esc(t.ghiChu||"")}</td></tr>`}).join("")}</tbody></table></div>
  ${ed?`<form class="frm row7" id="tf"><label class="field">Kênh<select id="t-k">${opt(CHANNELS.map(c=>c.k),"TikTok chính")}</select></label><label class="field">Sản phẩm<select id="t-s">${opt(skOpts(),"BT")}</select></label><label class="field">Tuyến<select id="t-t">${opt(LISTS.tuyen,"How-to")}</select></label><label class="field">Vai trò<input id="t-v" value="Khơi nhu cầu"></label><label class="field">Số lượng<input id="t-n" type="number" value="4"></label><label class="field">Phụ trách<select id="t-p">${opt(userOpts(),"u_may")}</select></label><button class="btn">Thêm tuyến</button></form><p class="hint">Tuyến đã có thẻ thì không xóa được; muốn bớt, giảm "Số lượng KH" rồi xóa thẻ thừa ở Lịch content.</p>`:""}</section>`;
  b.querySelectorAll("[data-pl]").forEach(x=>x.onchange=()=>{DB.mutate(ME.name,"sửa pillar",dt=>{const p=dt.pillars[+x.dataset.pl];p[x.dataset.f]=x.dataset.f==="kh"?Math.max(0,+x.value||0):x.value});toast("Đã lưu");renderMain()});
  b.querySelectorAll("[data-tu]").forEach(x=>x.onchange=()=>{DB.mutate(ME.name,"sửa tuyến",dt=>{const t=dt.tuyen[+x.dataset.tu];t[x.dataset.f]=x.dataset.f==="kh"?Math.max(0,+x.value||0):x.value});toast("Đã lưu");renderMain()});
  b.querySelectorAll("[data-pdel]").forEach(x=>x.onclick=()=>{if(x.dataset.ok){DB.mutate(ME.name,"xóa pillar",dt=>dt.pillars.splice(+x.dataset.pdel,1));renderMain()}else{x.dataset.ok=1;x.textContent="Bấm lần nữa"}});
  b.querySelectorAll("[data-tdel]").forEach(x=>x.onclick=()=>{if(x.dataset.ok){DB.mutate(ME.name,"xóa tuyến",dt=>dt.tuyen.splice(+x.dataset.tdel,1));renderMain()}else{x.dataset.ok=1;x.textContent="Bấm lần nữa"}});
  bindAddProd(b);
  if($("#padd"))$("#padd").onclick=()=>{DB.mutate(ME.name,"thêm pillar",dt=>dt.pillars.push({ma:"PIL-2610-"+String(dt.pillars.length+1).padStart(2,"0"),sku:"BT",kenh:"TikTok chính",vaiTro:"",mucTieu:"",kh:0,dinhDang:"Video",idea:"",nguoi:"u_oanh",ghiChu:""}));renderMain()};
  if($("#pub2"))$("#pub2").onclick=()=>{let n=0;DB.mutate(ME.name,"phát hành thẻ",dt=>{n=publishPlan(dt)});toast(n?`Đã sinh ${n} thẻ vào cột Chưa giao`:"Đủ thẻ theo kế hoạch");renderMain()};
  if($("#tf"))$("#tf").onsubmit=e=>{e.preventDefault();DB.mutate(ME.name,"thêm tuyến",dt=>dt.tuyen.push({ma:"T10-"+$("#t-s").value+"-"+String(dt.tuyen.length+1).padStart(2,"0"),kenh:$("#t-k").value,sku:$("#t-s").value,tuyen:$("#t-t").value,vaiTro:$("#t-v").value,kh:+$("#t-n").value||1,nguoi:$("#t-p").value,kiemChung:"Giả thuyết",maInsight:"",ghiChu:""}));renderMain()};
}
function stepSelect(c){
  if(!canMove(ME,c)){return stepPill(c)}
  const nx=nextAct(c);const o=[[c.step,stepName(c.step)]];if(nx)o.push([nx[1],"→ "+nx[0]]);if(["dkb","dvd"].includes(c.step)&&can(ME,"viec.duyet"))o.push(["__back","↩ Trả lại, cần sửa"]);
  if(c.step==="cg")return `<select data-assign="${c.id}">${opt(userOpts("Giao cho…"),"")}</select>`;
  return o.length>1?`<select data-step="${c.id}" class="st-${c.step}${isLate(c)?" late":""}">${opt(o,c.step)}</select>`:stepPill(c);
}
function lichKenh(b,C,kenh){
  const ch=chOf(kenh),cs=C.slice().sort((a,b)=>a.day-b.day),all=D().cards.filter(c=>c.kenh===kenh);
  const head=`<div class="grid kpis">${kpi("Kế hoạch",all.length)}${kpi("Đã tạo",all.filter(c=>c.step!=="cg"&&c.step!=="kb").length)}${kpi("Đã duyệt",all.filter(c=>stepIdx(c.step)>=stepIdx("dang")).length)}${kpi("Đã đăng",all.filter(c=>c.step==="xong").length,"","var(--green)")}${kpi("Còn thiếu",all.filter(c=>c.step!=="xong").length)}${ch.needId?kpi("Đơn · doanh thu",nf(sum(all,c=>c.don)),money(sum(all,c=>c.gmv))):""}</div>`;
  if(ch.needId)b.innerHTML=head+`<section class="card flush"><div class="scroll-hint">Kéo thanh cuộn ngang ở đáy khung (hoặc giữ Shift + lăn chuột) để xem thêm cột →</div><div class="tbl sheet"><table><thead><tr class="grp"><th colspan="6">KẾ HOẠCH</th><th colspan="2">KỊCH BẢN & TRIỂN KHAI</th><th colspan="3">SẢN XUẤT & DUYỆT</th><th colspan="7">ĐĂNG & KẾT QUẢ</th></tr><tr><th>Mã video</th><th>Ngày</th><th>Sản phẩm</th><th>Nguồn</th><th>Tuyến</th><th>Ưu tiên</th><th>Hook text</th><th>Người làm</th><th>Link video</th><th>Duyệt</th><th>CEO check</th><th>Trạng thái</th><th>Caption</th><th>Link đăng</th><th>ID TikTok</th><th class="n">View</th><th class="n">Đơn</th><th class="n">GMV</th></tr></thead><tbody>
   ${cs.map(c=>`<tr data-card="${c.id}" class="${isLate(c)?"late":""}"><td class="mono">${c.id}</td><td>${dd(c.day)}</td><td>${swatch(c.sku)}${sk(c.sku).n}</td><td>${esc(c.nguon)}${c.repostOf?`<small>từ ${c.repostOf}</small>`:""}</td><td>${esc(c.tuyen)}</td><td>${esc(c.uuTien)}</td><td class="wide">${esc(c.hookText||c.yTuong)}</td><td>${c.nguoi?esc(userName(c.nguoi)):`<span class="t-amb">chưa giao</span>`}</td><td>${c.linkVideo?`<a href="${esc(c.linkVideo)}" target="_blank" rel="noopener">mở</a>`:"—"}</td><td>${pill(sheetDuyet(c),sheetDuyet(c)==="Đã duyệt"?"grn":sheetDuyet(c)==="Cần sửa"?"amb":"gry")}</td><td>${pill(c.ceo,c.ceo==="PASS"?"grn":c.ceo==="KHÔNG DÙNG"?"red":"gry")}</td><td>${stepSelect(c)}</td><td class="wide">${esc((c.caption||"").slice(0,90))||"—"}</td><td>${c.linkDang?`<a href="${esc(c.linkDang)}" target="_blank" rel="noopener">mở</a>`:c.step==="xong"?`<span class="t-red">thiếu</span>`:"—"}</td><td class="mono">${c.tiktokId?c.tiktokId.slice(-6)+"…":c.step==="xong"?`<span class="t-red">thiếu</span>`:"—"}</td><td class="n">${c.view?nf(c.view):"—"}</td><td class="n">${c.don||"—"}</td><td class="n">${c.gmv?money(c.gmv):"—"}</td></tr>`).join("")||`<tr><td colspan="18" class="empty">Không có nội dung.</td></tr>`}</tbody></table></div></section>`;
  else b.innerHTML=head+`<section class="card flush"><div class="scroll-hint">Kéo thanh cuộn ngang ở đáy khung (hoặc giữ Shift + lăn chuột) để xem thêm cột →</div><div class="tbl sheet"><table><thead><tr class="grp"><th colspan="5">KẾ HOẠCH</th><th colspan="4">NỘI DUNG & HÌNH ẢNH</th><th colspan="3">DUYỆT</th><th colspan="3">ĐĂNG & KẾT QUẢ</th></tr><tr><th>Mã bài</th><th>Ngày</th><th>SKU / chủ đề</th><th>Tuyến</th><th>Định dạng</th><th>Nội dung</th><th>Caption</th><th>Link ảnh</th><th>Link video</th><th>Người viết</th><th>CEO check</th><th>Trạng thái</th><th>Link bài đăng</th><th>Ngày đăng</th><th>Kết quả</th></tr></thead><tbody>
   ${cs.map(c=>`<tr data-card="${c.id}" class="${isLate(c)?"late":""}"><td class="mono">${c.id}</td><td>${dd(c.day)}</td><td>${swatch(c.sku)}${sk(c.sku).n}</td><td>${esc(c.tuyen)}${c.repostOf?`<small>đăng lại từ ${c.repostOf}</small>`:""}</td><td>${pill(c.dangVideo,c.dangVideo==="Video/Reel"?"vio":c.dangVideo==="Carousel"?"blu":"pnk")}</td><td class="wide">${esc(c.noiDung||c.yTuong)}</td><td class="wide">${esc((c.caption||"").slice(0,90))||"—"}</td><td>${c.linkAnh?`<a href="${esc(c.linkAnh)}" target="_blank" rel="noopener">mở</a>`:"—"}</td><td>${c.linkVideo?`<a href="${esc(c.linkVideo)}" target="_blank" rel="noopener">mở</a>`:"—"}</td><td>${c.nguoi?esc(userName(c.nguoi)):`<span class="t-amb">chưa giao</span>`}</td><td>${pill(c.ceo,c.ceo==="PASS"?"grn":"gry")}</td><td>${stepSelect(c)}</td><td>${c.linkDang?`<a href="${esc(c.linkDang)}" target="_blank" rel="noopener">mở</a>`:c.step==="xong"?`<span class="t-red">thiếu</span>`:"—"}</td><td>${c.ngayDang?dd(c.ngayDang):"—"}</td><td>${esc(c.ketQua)||"—"}</td></tr>`).join("")||`<tr><td colspan="15" class="empty">Không có bài.</td></tr>`}</tbody></table></div></section>`;
}

/* =====================================================================
   6. BẢNG CÔNG VIỆC (kanban: giao + duyệt)
   ===================================================================== */
let BF={k:"",w:"tuan"};
function pCongViec(m){
  const td=D().settings.today,cgN=D().cards.filter(c=>c.step==="cg"&&c.day<=td+7).length;
  m.innerHTML=H("Bảng công việc")+`<div class="filters"><select id="bw">${opt([["tuan","Tuần này + tuần sau + việc trễ"],["all","Cả tháng"]],BF.w)}</select><select id="bk">${opt([["","Mọi kênh"]].concat(CHANNELS.map(c=>c.k)),BF.k)}</select><select id="bs">${opt([["","Mọi sản phẩm"]].concat(skOpts()),LF.sku)}</select><select id="bn">${opt([["","Mọi người"]].concat(workers().map(u=>[u.id,u.name])),LF.nguoi)}</select><span class="sp"></span>${can(ME,"viec.giao")?`<button class="btn" id="auto">Giao theo gợi ý (${cgN} thẻ 7 ngày tới)</button>`:""}</div><div class="board" id="board"></div>`;
  $("#bw").onchange=e=>{BF.w=e.target.value;renderMain()};$("#bk").onchange=e=>{BF.k=e.target.value;renderMain()};$("#bs").onchange=e=>{LF.sku=e.target.value;renderMain()};$("#bn").onchange=e=>{LF.nguoi=e.target.value;renderMain()};
  if($("#auto"))$("#auto").onclick=()=>{let n=0;DB.mutate(ME.name,"giao thẻ theo gợi ý",dt=>dt.cards.filter(c=>c.step==="cg"&&c.day<=td+7).forEach(c=>{c.nguoi=c.goiy||"u_may";c.step="kb";n++}));toast("Đã giao "+n+" thẻ");renderMain()};
  const vis=D().cards.filter(c=>(!BF.k||c.kenh===BF.k)&&(!LF.sku||c.sku===LF.sku)&&(!LF.nguoi||c.nguoi===LF.nguoi)&&(BF.w==="all"||isLate(c)||(c.day>=td-2&&c.day<=td+10)));
  $("#board").innerHTML=STEPS.map(s=>{const cs=vis.filter(c=>c.step===s.id).sort((a,b)=>a.day-b.day);return `<div class="col col-${s.id}" data-col="${s.id}"><div class="col-h"><b>${s.t}</b><span>${cs.length}</span></div><div class="col-w">${s.who}</div>${cs.slice(0,30).map(c=>`<div class="kc${isLate(c)?" late":""}" data-card="${c.id}" draggable="true" style="border-left-color:${sk(c.sku).c}"><div class="kc-t">${esc(c.hookText||c.yTuong)}</div><div class="kc-m">${c.id} · ${chOf(c.kenh).short} · ${dd(c.day)}</div><div class="kc-m">${c.step==="cg"&&can(ME,"viec.giao")?`<select data-assign="${c.id}">${opt(userOpts("Giao cho…"),"")}</select> <small>gợi ý ${esc(userName(c.goiy))}</small>`:`<b>${esc(userName(c.nguoi)||"chưa giao")}</b>`}${c.step==="worker"?` <span class="spin"></span>`:""}${c.step==="xong"&&c.don?" · "+pill(c.don+" đơn","grn"):""}</div></div>`).join("")}${cs.length>30?`<div class="more">+${cs.length-30} thẻ</div>`:""}</div>`}).join("");
  $$(".kc").forEach(e=>e.ondragstart=ev=>ev.dataTransfer.setData("text/plain",e.dataset.card));
  $$(".col").forEach(col=>{col.ondragover=e=>{e.preventDefault();col.classList.add("drop")};col.ondragleave=()=>col.classList.remove("drop");col.ondrop=e=>{e.preventDefault();col.classList.remove("drop");const id=e.dataTransfer.getData("text/plain");const err=moveCard(ME,id,col.dataset.col);if(err){toast(err);openCard(id,{err})}renderMain()}});
}

/* =====================================================================
   7. NHÂN BẢN VIDEO WIN (VIDEO_WIN · DATA_HOOK_WINNER · KE_HOACH_NHAN_BAN)
   ===================================================================== */
function winners(){const d=D(),set=d.settings;
  const a=d.cards.filter(c=>c.don>0).map(c=>({key:c.tiktokId||c.id,cardId:c.id,ten:c.hookText||c.yTuong,sku:c.sku,kenh:c.kenh,nguoi:c.nguoi,view:c.view,don:c.don,gmv:c.gmv,nguon:"Video tháng này",tm:dd(c.day)}));
  const b=d.oldWins.map(o=>({key:o.id,ten:o.ten,sku:o.sku,kenh:o.kenh,nguoi:"",view:o.view,don:o.don,gmv:o.gmv,nguon:"Video cũ ("+o.tm+")",tm:o.tm,note:o.note}));
  return a.concat(b).sort((x,y)=>y.don-x.don||y.gmv-x.gmv).map((w,i)=>({...w,hang:i+1,loai:w.don>=set.winnerOrders?"Winner":w.don>=set.potential?"Tiềm năng":"Có đơn"}));}
let WP=null;
function pWin(m){
  const d=D(),tab=SUB.win||"rank",W=winners(),ed=can(ME,"win.sua");
  m.innerHTML=H("Nhân bản video win",`Winner ≥ ${d.settings.winnerOrders} đơn · Tiềm năng ≥ ${d.settings.potential} đơn`)+`<div class="grid kpis">${kpi("Winner",W.filter(w=>w.loai==="Winner").length,"","var(--green)")}${kpi("Tiềm năng",W.filter(w=>w.loai==="Tiềm năng").length)}${kpi("Kế hoạch nhân bản",d.winPlans.length)}${kpi("Bản nhân đã đăng",d.cards.filter(c=>c.winPlan&&c.step==="xong").length+"/"+d.cards.filter(c=>c.winPlan).length)}${kpi("Đơn từ bản nhân",nf(sum(d.cards.filter(c=>c.winPlan),c=>c.don)),money(sum(d.cards.filter(c=>c.winPlan),c=>c.gmv)))}</div>
   <div class="tabs">${[["rank","Bảng xếp hạng"],["plan","Kế hoạch nhân bản"]].map(([k,t])=>`<button data-sub="${k}" class="${k===tab?"on":""}">${t}</button>`).join("")}</div><div id="wb"></div>`;
  const b=$("#wb");
  if(tab==="rank")b.innerHTML=`<section class="card">${tbl(["Hạng","Video","Sản phẩm","Kênh","Nguồn","Người làm","View","Đơn","GMV","Phân loại","Bản nhân",""],W.slice(0,40).map(w=>{const plans=d.winPlans.filter(p=>p.src===w.key);return `<tr${w.cardId?` data-card="${w.cardId}"`:""}><td class="n"><b>${w.hang}</b></td><td class="wide">${esc(w.ten)}${w.note?`<small>${esc(w.note)}</small>`:""}</td><td>${swatch(w.sku)}${sk(w.sku).n}</td><td>${chOf(w.kenh).short}</td><td>${esc(w.nguon)}</td><td>${esc(userName(w.nguoi))}</td><td class="n">${nf(w.view)}</td><td class="n"><b>${nf(w.don)}</b></td><td class="n">${money(w.gmv)}</td><td>${pill(w.loai,w.loai==="Winner"?"grn":w.loai==="Tiềm năng"?"amb":"gry")}</td><td class="n">${sum(plans,p=>p.soBan)}</td><td>${ed&&w.loai!=="Có đơn"?`<button class="btn sm" data-mkplan="${esc(w.key)}">Lên kế hoạch</button>`:""}</td></tr>`}))}</section>`;
  else b.innerHTML=d.winPlans.map(p=>{const cs=d.cards.filter(c=>c.winPlan===p.id);return `<section class="card"><div class="card-h"><h2>${p.id} · ${esc(p.srcTen)}</h2>${pill(sk(p.sku).n)} ${pill(cs.filter(c=>c.step==="xong").length+"/"+p.soBan+" đã đăng","blu")}</div>
    <div class="grid cols3"><dl class="kv"><dt>Điểm thắng</dt><dd>${esc(p.diemThang)}</dd><dt>Điểm yếu</dt><dd>${esc(p.diemYeu)}</dd></dl><dl class="kv"><dt>Giữ nguyên</dt><dd>${esc(p.giu)}</dd><dt>Thay đổi</dt><dd>${esc(p.doi)}</dd></dl><dl class="kv"><dt>Kênh</dt><dd>${p.kenh}</dd><dt>Phụ trách</dt><dd>${esc(userName(p.nguoi))}</dd><dt>Hạn</dt><dd>${dd(p.deadline)}</dd></dl></div>
    ${tbl(["Mã bản nhân","Hook","Người","Trạng thái","Ngày đăng","View","Đơn","GMV"],cs.map(c=>`<tr data-card="${c.id}"><td class="mono">${c.id}</td><td>${esc(c.hookText||c.yTuong)}</td><td>${esc(userName(c.nguoi)||"chưa giao")}</td><td>${stepPill(c)}</td><td>${c.ngayDang?dd(c.ngayDang):"—"}</td><td class="n">${c.view?nf(c.view):"—"}</td><td class="n">${c.don||"—"}</td><td class="n">${c.gmv?money(c.gmv):"—"}</td></tr>`))}
    <label class="field">Kết luận<textarea rows="2" data-kl="${p.id}" ${ed?"":"disabled"}>${esc(p.ketLuan)}</textarea></label></section>`}).join("")||`<section class="card"><p class="empty">Chưa có kế hoạch nhân bản. Vào Bảng xếp hạng, bấm "Lên kế hoạch".</p></section>`;
  b.querySelectorAll("[data-kl]").forEach(t=>t.onchange=()=>DB.mutate(ME.name,"kết luận "+t.dataset.kl,dt=>dt.winPlans.find(p=>p.id===t.dataset.kl).ketLuan=t.value));
  b.querySelectorAll("[data-mkplan]").forEach(x=>x.onclick=()=>openWinPlan(W.find(w=>w.key===x.dataset.mkplan)));
}
function openWinPlan(w){
  $("#drawerIn").innerHTML=`<div class="dh"><h2>Kế hoạch nhân bản</h2><button class="btn sm" id="dx">Đóng</button></div><p><b>${esc(w.ten)}</b><br><span class="hint">${nf(w.don)} đơn · ${money(w.gmv)} · ${esc(w.nguon)}</span></p>
   <form class="frm" id="wpf"><label class="field">Điểm thắng (vì sao bán)<textarea id="wp-t" rows="2" required></textarea></label><label class="field">Điểm yếu<input id="wp-y"></label><label class="field">Biến số giữ nguyên<input id="wp-g" value="Cảnh mở + câu mở"></label><label class="field">Biến số thay đổi<input id="wp-d" value="Người nói, bối cảnh"></label>
   <div class="row4"><label class="field">Số phiên bản<input id="wp-n" type="number" min="1" max="10" value="3"></label><label class="field">Kênh<select id="wp-k">${opt(CHANNELS.filter(c=>c.needId).map(c=>c.k),w.kenh)}</select></label><label class="field">Phụ trách<select id="wp-p">${opt(userOpts(),w.nguoi||"u_quynh")}</select></label><label class="field">Hạn (ngày)<input id="wp-h" type="number" min="1" max="31" value="${Math.min(31,D().settings.today+5)}"></label></div><button class="btn pri big">Tạo kế hoạch + thẻ bản nhân</button></form>`;
  $("#drawer").hidden=false;$("#dx").onclick=closeDrawer;
  $("#wpf").onsubmit=e=>{e.preventDefault();const n=+$("#wp-n").value||3;let pid;DB.mutate(ME.name,"lập kế hoạch nhân bản "+w.ten.slice(0,30),dt=>{pid="WP-"+String(dt.winPlans.length+1).padStart(2,"0");dt.winPlans.push({id:pid,src:w.key,srcTen:w.ten,sku:w.sku,diemThang:$("#wp-t").value,diemYeu:$("#wp-y").value,giu:$("#wp-g").value,doi:$("#wp-d").value,soBan:n,kenh:$("#wp-k").value,nguoi:$("#wp-p").value,deadline:+$("#wp-h").value,ketLuan:""});
    for(let i=0;i<n;i++)dt.cards.push(newCard(dt,{sku:w.sku,kenh:$("#wp-k").value,day:Math.min(31,+$("#wp-h").value-n+1+i),nguon:"Nhân bản winner",tuyen:"Nhân bản winner",yTuong:w.ten.slice(0,60)+" (bản "+(i+1)+": "+$("#wp-d").value+")",winPlan:pid,winSrc:w.key,nguoi:$("#wp-p").value,goiy:$("#wp-p").value,step:"kb"}))});closeDrawer();SUB.win="plan";toast(`Đã tạo ${n} thẻ bản nhân cho ${userName($("#wp-p").value)}`);renderMain()};
}

/* =====================================================================
   8. ORDER DIGITAL (ORDER_DIGITAL)
   ===================================================================== */
function pOrder(m){
  const d=D(),O=d.orders,C=d.cards,td=d.settings.today,edA=can(ME,"order.sua"),gi=can(ME,"viec.giao");
  const done=o=>C.filter(c=>c.order===o.ma&&stepIdx(c.step)>=stepIdx("dang")).length;
  m.innerHTML=H("Order video của Digital")+`<div class="grid kpis">${kpi("Order tháng",O.length)}${kpi("Video cần",sum(O,o=>o.sl))}${kpi("Đã duyệt",sum(O,done),"","var(--green)")}${kpi("Trễ hạn",O.filter(o=>o.trangThai!=="Xong"&&o.han<td).length,"",O.some(o=>o.trangThai!=="Xong"&&o.han<td)?"var(--red)":"")}${kpi("Chi Ads theo order",money(sum(O,o=>o.chi)),"ROAS "+(sum(O,o=>o.chi)?(sum(O,o=>o.dtAds)/sum(O,o=>o.chi)).toFixed(1):0)+"×")}</div>
  <section class="card flush"><div class="scroll-hint">Kéo thanh cuộn ngang ở đáy khung (hoặc giữ Shift + lăn chuột) để xem thêm cột →</div><div class="tbl sheet"><table><thead><tr><th>Mã order</th><th>Ngày</th><th>Người order</th><th>Kênh chạy</th><th>Sản phẩm</th><th>Mục đích / offer</th><th class="n">Số video</th><th>Deadline</th><th>Brief / hook</th><th>Giao cho</th><th class="n">Đã duyệt</th><th class="n">Còn thiếu</th><th>Trạng thái</th><th>Cảnh báo</th><th class="n">Chi phí ads</th><th class="n">Đơn ads</th><th class="n">Doanh thu ads</th><th class="n">ROAS</th><th>Feedback của Digital</th></tr></thead><tbody>
  ${O.map(o=>{const dn=done(o),late=o.trangThai!=="Xong"&&o.han<td;return `<tr class="${late?"late":""}"><td class="mono">${o.ma}</td><td>${o.ngay}</td><td>${esc(userName(o.nguoiOrder))}</td><td>${o.kenh}</td><td>${swatch(o.sku)}${sk(o.sku).n}</td><td>${esc(o.muc)}</td><td class="n">${o.sl}</td><td>${dd(o.han)}</td><td>${esc(o.brief)}${o.linkMau?`<small><a href="${esc(o.linkMau)}" target="_blank" rel="noopener">mẫu</a></small>`:""}</td><td>${gi?`<select data-og="${o.ma}">${opt(userOpts("Chưa giao"),o.giao)}</select>`:esc(userName(o.giao)||"chưa giao")}</td><td class="n">${dn}</td><td class="n">${Math.max(0,o.sl-dn)}</td><td>${pill(o.trangThai,o.trangThai==="Xong"?"grn":o.trangThai==="Đang làm"?"blu":"gry")}</td><td>${late?pill("TRỄ HẠN","red"):""}</td>${["chi","donAds","dtAds"].map(k=>`<td class="n">${edA?`<input class="num" data-on="${o.ma}" data-k="${k}" value="${k==="donAds"?o[k]:o[k]/1e6}" title="${k==="donAds"?"đơn":"triệu đồng"}">`:k==="donAds"?nf(o[k]):money(o[k])}</td>`).join("")}<td class="n">${o.chi?(o.dtAds/o.chi).toFixed(1)+"×":"—"}</td><td>${edA?`<input data-on="${o.ma}" data-k="fb" value="${esc(o.fb)}" placeholder="Video nào chạy tốt">`:esc(o.fb)}</td></tr>`}).join("")}</tbody></table></div><p class="hint" style="padding:0 16px 12px">Chi phí và doanh thu Ads nhập theo triệu đồng.</p></section>
  ${can(ME,"order.tao")?`<section class="card"><div class="card-h"><h2>Gửi order mới</h2></div><form class="frm" id="of"><div class="row4"><label class="field">Sản phẩm<select id="o-s">${opt(skOpts(),"BT")}</select></label><label class="field">Kênh chạy<select id="o-k">${opt(["Facebook Ads","TikTok Ads"],"Facebook Ads")}</select></label><label class="field">Số video<input id="o-n" type="number" min="1" max="10" value="2"></label><label class="field">Deadline (ngày)<input id="o-h" type="number" min="1" max="31" value="${Math.min(31,td+5)}"></label></div><label class="field">Mục đích / offer<input id="o-m" required></label><label class="field">Brief / yêu cầu hook<textarea id="o-b" rows="2" required></textarea></label><label class="field">Link brief / video mẫu<input id="o-l"></label><label class="field">Tệp brief (≤10MB)<input type="file" id="o-f" multiple></label><button class="btn pri big">Gửi order</button></form></section>`:""}`;
  m.querySelectorAll("[data-og]").forEach(s=>s.onchange=()=>{DB.mutate(ME.name,`giao order ${s.dataset.og} cho ${userName(s.value)}`,dt=>{const o=dt.orders.find(x=>x.ma===s.dataset.og);o.giao=s.value;if(o.trangThai==="Mới")o.trangThai="Đang làm";dt.cards.filter(c=>c.order===o.ma&&c.step==="cg").forEach(c=>{c.nguoi=s.value;c.step="kb"})});renderMain()});
  m.querySelectorAll("[data-on]").forEach(i=>i.onchange=()=>DB.mutate(ME.name,"cập nhật order "+i.dataset.on,dt=>{const o=dt.orders.find(x=>x.ma===i.dataset.on);o[i.dataset.k]=i.dataset.k==="fb"?i.value:i.dataset.k==="donAds"?+i.value||0:(+i.value||0)*1e6}));
  if($("#of"))$("#of").onsubmit=async e=>{e.preventDefault();const files=await saveFiles($("#o-f").files);let ma;const n=Math.max(1,+$("#o-n").value||1),han=Math.min(31,Math.max(1,+$("#o-h").value||td+5));
    DB.mutate(ME.name,"gửi order",dt=>{ma="ORD-"+String(dt.orders.length+3).padStart(4,"0");dt.orders.push({ma,ngay:dd(dt.settings.today),nguoiOrder:ME.id,kenh:$("#o-k").value,sku:$("#o-s").value,muc:$("#o-m").value,sl:n,han,brief:$("#o-b").value,linkMau:$("#o-l").value,giao:"",trangThai:"Mới",chi:0,donAds:0,dtAds:0,fb:"",files});
      for(let i=0;i<n;i++)dt.cards.push(newCard(dt,{sku:$("#o-s").value,kenh:"TikTok chính",day:han,nguon:"Order Digital",order:ma,tuyen:"Order Digital",yTuong:"Order "+ma+": "+$("#o-m").value,noiDung:$("#o-b").value,goiy:"u_hoa",files}))});toast("Đã gửi "+ma+", chờ Oanh giao");renderMain()};
}

/* =====================================================================
   9. KHO VIDEO CŨ (KHO_VIDEO_CU)
   ===================================================================== */
let KF={s:"",d:"ok"};
function pKho(m){
  const K=D().kho,isOk=k=>(k.duyet||"").toLowerCase()==="đã duyệt",gan=can(ME,"kho.gan");
  const list=K.filter(k=>(!KF.s||k.sku===KF.s)&&(KF.d==="all"||(KF.d==="ok"?isOk(k)&&!k.maDang:KF.d==="used"?!!k.maDang:!isOk(k))));
  m.innerHTML=H("Kho video cũ",`${K.length} video · đọc từ tab KHO_VIDEO_CU`)+`${gan?`<div class="note">Cần xếp nhiều video một lúc: dùng <button class="btn sm pri" data-go="phanbo">Phân bổ lịch đăng</button> (chọn nhiều video, tự xếp vào ô trống theo ngày × kênh).</div>`:""}<div class="grid kpis">${kpi("Video trong kho",K.length)}${kpi("Đã duyệt, chưa dùng",K.filter(k=>isOk(k)&&!k.maDang).length,"","var(--green)")}${kpi("Đã dùng tháng này",K.filter(k=>k.maDang).length)}${kpi("Cần duyệt / sửa",K.filter(k=>!isOk(k)).length)}</div>
  <div class="filters"><select id="ks">${opt([["","Mọi sản phẩm"]].concat([...new Set(K.map(k=>k.sku))].map(k=>[k,sk(k).n+" ("+K.filter(x=>x.sku===k).length+")"])),KF.s)}</select><select id="kd">${opt([["ok","Đã duyệt, chưa dùng"],["used","Đã dùng tháng này"],["no","Cần duyệt / sửa"],["all","Tất cả"]],KF.d)}</select></div>
  <section class="card flush"><div class="scroll-hint">Kéo thanh cuộn ngang ở đáy khung (hoặc giữ Shift + lăn chuột) để xem thêm cột →</div><div class="tbl sheet"><table><thead><tr><th>Mã video</th><th>SKU</th><th>Nhân sự</th><th>Tuyến / concept</th><th>Duyệt</th><th>Video</th><th>Kênh đề xuất T10</th><th>Quyền sử dụng</th><th>Cần chỉnh sửa</th><th>Trạng thái dùng</th><th>Mã đăng T10</th><th></th></tr></thead><tbody>
  ${list.slice(0,120).map(k=>`<tr><td class="mono">${k.ma}</td><td>${esc(k.skuText)}</td><td>${esc(k.nguoi)}</td><td>${esc(k.tuyen)}</td><td>${pill(k.duyet||"trống",isOk(k)?"grn":"amb")}</td><td>${k.link?`<a href="${esc(k.link)}" target="_blank" rel="noopener">xem</a>`:""}</td><td>${esc(k.kenhDeXuat)||"—"}</td><td>${esc(k.quyen)}</td><td>${esc(k.canSua)||"—"}</td><td>${pill(k.trangThai,k.maDang?"grn":"gry")}</td><td>${k.maDang?`<span class="mono lnk" data-card="${k.maDang}">${k.maDang}</span>`:"—"}</td><td>${gan&&isOk(k)&&!k.maDang?`<button class="btn sm" data-kg="${k.ma}">Dùng cho kênh</button>`:""}</td></tr>`).join("")||`<tr><td colspan="12" class="empty">Không có video.</td></tr>`}</tbody></table></div>${list.length>120?`<p class="hint" style="padding:0 16px 12px">Đang hiện 120/${list.length}.</p>`:""}</section>`;
  $("#ks").onchange=e=>{KF.s=e.target.value;renderMain()};$("#kd").onchange=e=>{KF.d=e.target.value;renderMain()};
  m.querySelectorAll("[data-kg]").forEach(x=>x.onclick=()=>{const k=K.find(y=>y.ma===x.dataset.kg);
    $("#drawerIn").innerHTML=`<div class="dh"><h2>Dùng ${k.ma} cho kênh</h2><button class="btn sm" id="dx">Đóng</button></div><p>${esc(k.skuText)} · ${esc(k.tuyen)} · <a href="${esc(k.link)}" target="_blank" rel="noopener">xem video</a></p><form class="frm" id="kgf"><label class="field">Kênh<select id="kg-k">${opt(CHANNELS.filter(c=>c.needId).map(c=>c.k),"TikTok Via 2")}</select></label><label class="field">Lý do chọn kênh<input id="kg-l" value="Video tồn phù hợp"></label><label class="field">Quyền sử dụng<select id="kg-q">${opt(["Đã kiểm — dùng được","Cần hỏi lại","Không dùng"],"Đã kiểm — dùng được")}</select></label><label class="field">Cần chỉnh sửa gì<input id="kg-s" value="Đổi hook, chèn chữ mới"></label><label class="field">Giao cho<select id="kg-p">${opt(userOpts(),"u_may")}</select></label><label class="field">Ngày đăng<input id="kg-d" type="number" min="1" max="31" value="${Math.min(31,D().settings.today+2)}"></label><button class="btn pri big">Tạo thẻ đổi hook</button></form>`;
    $("#drawer").hidden=false;$("#dx").onclick=closeDrawer;
    $("#kgf").onsubmit=e=>{e.preventDefault();if($("#kg-q").value==="Không dùng"){toast("Video không được dùng");return}let cid;DB.mutate(ME.name,`dùng ${k.ma} cho ${$("#kg-k").value}`,dt=>{const kk=dt.kho.find(y=>y.ma===k.ma);const sKey=dt.products.some(p=>p.k===kk.sku)?kk.sku:"XM";const c=newCard(dt,{sku:sKey,kenh:$("#kg-k").value,day:+$("#kg-d").value,nguon:"Footage cũ",tuyen:"Đổi hook video tồn",yTuong:"Đổi hook "+kk.ma+" · "+kk.tuyen,linkVideo:kk.link,nguoi:$("#kg-p").value,goiy:$("#kg-p").value,step:"kb"});dt.cards.push(c);cid=c.id;Object.assign(kk,{kenhDeXuat:$("#kg-k").value,lyDo:$("#kg-l").value,quyen:$("#kg-q").value,canSua:$("#kg-s").value,trangThai:"Đã lên lịch",maDang:c.id})});closeDrawer();toast("Đã tạo thẻ "+cid);renderMain()};
  });
}

/* =====================================================================
   10. NHẬP BÁO CÁO (TikTok · Ads Facebook)
   ===================================================================== */
let LASTREP=null;
function pBaoCao(m){
  const d=D(),tab=SUB.baocao||(can(ME,"baocao.tiktok")?"tt":"ads");const tabs=[["tt","Báo cáo TikTok",can(ME,"baocao.tiktok")],["ads","Báo cáo Ads Facebook",can(ME,"baocao.ads")],["ls","Lịch sử nhập",true]].filter(t=>t[2]);
  m.innerHTML=H("Nhập báo cáo")+`<div class="tabs">${tabs.map(([k,t])=>`<button data-sub="${k}" class="${k===tab?"on":""}">${t}</button>`).join("")}</div><div id="bb"></div>`;
  const b=$("#bb");
  if(tab==="tt"){b.innerHTML=`<section class="card"><div class="card-h"><h2>File "Video Performance List"</h2></div><ol class="lessons"><li>TikTok Shop → Phân tích → Video → chọn 7 ngày tuần trước → Xuất.</li><li>Chọn tài khoản, kéo file vào ô dưới. Làm lần lượt từng tài khoản.</li></ol><div class="frm row4"><label class="field">Tài khoản<select id="tt-k">${opt(CHANNELS.filter(c=>c.needId).map(c=>c.k),"TikTok chính")}</select></label></div>${dropZone("tt")}</section><div id="rep">${LASTREP&&LASTREP.loai==="tt"?LASTREP.html:""}</div>`;
    bindDrop("tt",async(f)=>{const rows=await readXlsx(f);const res=parseTikTok(rows,f.name);if(res.err){toast(res.err);return}const cl=applyTikTok(ME,res,$("#tt-k").value);LASTREP={loai:"tt",html:ttReport(res,cl)};toast("Đã nhập: "+cl.match.length+" video khớp");renderMain()})}
  if(tab==="ads"){b.innerHTML=`<section class="card"><div class="card-h"><h2>File Ads Facebook (Trình quản lý quảng cáo)</h2></div><ol class="lessons"><li>Trình quản lý quảng cáo → cấp Chiến dịch → chọn 7 ngày tuần trước → Báo cáo → Xuất bảng (.xlsx).</li><li>Cần các cột: Tên chiến dịch, Số tiền đã chi tiêu, Lượt mua, Giá trị chuyển đổi mua hàng (có thì thêm: Lượt bắt đầu cuộc trò chuyện).</li><li>Đặt tên chiến dịch theo quy ước NGƯỜI-MÃSP-CD/MESS (VA, Thao, Duan · BTVN, TINHDAU, XM, TLAi…) để app tự tách theo người và sản phẩm.</li></ol><div class="frm row4"><label class="field">Tuần<select id="ad-w">${opt(WEEKS.map(w=>[w.w,"Tuần "+w.w+" ("+dd(w.tu)+" – "+dd(w.den)+")"]),Math.max(1,weekOf(d.settings.today)-1))}</select></label></div>${dropZone("ads")}<div class="acts"><button class="btn sm" id="ad-demo">Thử với file mẫu</button></div></section><div id="rep">${LASTREP&&LASTREP.loai==="ads"?LASTREP.html:adsSummary()}</div>`;
    const go=rows=>{const res=parseAds(rows,LASTNAME);if(res.err){toast(res.err);return}const wk=res.den&&res.den<=MONTH.ndays&&/-10-|\/10\//.test((res.recs[0]||{}).den||"")?weekOf(res.den):+$("#ad-w").value;const S=applyAds(ME,res,wk);LASTREP={loai:"ads",html:adsSummary(res,S)};toast("Đã nhập "+res.recs.length+" chiến dịch");renderMain()};
    bindDrop("ads",async f=>{LASTNAME=f.name;go(await readXlsx(f))});
    $("#ad-demo").onclick=()=>{const w=WEEKS[+$("#ad-w").value-1],f=x=>"2026-10-"+String(x).padStart(2,"0"),a=f(w.tu),z=f(w.den);LASTNAME="file-mau-ads-tuan-"+w.w+".xlsx";go([["Tên chiến dịch","Ngày bắt đầu báo cáo","Ngày kết thúc báo cáo","Số tiền đã chi tiêu (VND)","Lượt mua","Giá trị chuyển đổi mua hàng","Lượt bắt đầu cuộc trò chuyện qua tin nhắn"],["VA-BTVN-CD-T10",a,z,5200000,124,10200000,0],["Thao-TINHDAU-CD-SN2010",a,z,4100000,98,6300000,0],["Duan-XM-MESS-T10",a,z,2300000,0,0,260],["VA-TLAi-CD",a,z,1200000,21,980000,0],["[AVN] tt ailla vietnam",a,z,600000,0,0,0]])};
  }
  if(tab==="ls")b.innerHTML=`<section class="card">${tbl(["Lúc","Loại","Tài khoản","Người nhập","File","Khoảng ngày","Tuần","Kết quả"],d.imports.map(i=>`<tr><td>${esc(i.at)}</td><td>${pill(i.loai,i.loai==="TikTok"?"pnk":"blu")}</td><td>${esc(i.kenh)}</td><td>${esc(i.by)}</td><td>${esc(i.file)}</td><td>${esc(i.range)}</td><td class="n">${i.tuan}</td><td>${i.loai==="TikTok"?`${i.sum.match.n} khớp · ${i.sum.stray.n} chưa có thẻ · ${i.sum.auto.n} tự tạo · cũ ${money(i.sum.old.gmv)}`:`chi ${money(i.sum.chi)} · ${nf(i.sum.mua)} đơn · ${money(i.sum.gt)}`}</td></tr>`))}</section>`;
}
let LASTNAME="";
const dropZone=k=>`<label class="drop" id="dz-${k}"><b>Kéo file Excel vào đây</b><span>hoặc bấm để chọn (.xlsx, .csv)</span><input type="file" id="fi-${k}" accept=".xlsx,.xls,.csv" hidden></label>`;
function bindDrop(k,fn){const z=$("#dz-"+k);["dragover","dragenter"].forEach(ev=>z.addEventListener(ev,e=>{e.preventDefault();z.classList.add("on")}));["dragleave","drop"].forEach(ev=>z.addEventListener(ev,e=>{e.preventDefault();z.classList.remove("on")}));z.addEventListener("drop",e=>{const f=e.dataTransfer.files[0];if(f)fn(f)});$("#fi-"+k).onchange=e=>{const f=e.target.files[0];if(f)fn(f)}}
function readXlsx(f){return new Promise((res,rej)=>{if(typeof XLSX==="undefined"){toast("Chưa tải được thư viện đọc Excel (cần mạng)");rej();return}const r=new FileReader();r.onload=()=>{try{res(sheetRows(XLSX.read(r.result,{type:"array"})))}catch(e){toast("Không đọc được file");rej(e)}};r.readAsArrayBuffer(f)})}
function ttReport(res,cl){const s=cl.sum;return `<section class="card ok"><div class="card-h"><h2>Đã nhập ${esc(res.name)}</h2><span class="hint">${esc(res.range)}</span></div><div class="grid kpis">${kpi("Có thẻ, đã khớp",cl.match.length,money(s.match.gmv)+" · "+nf(s.match.don)+" đơn","var(--green)")}${kpi("Team đăng, chưa có thẻ",cl.stray.length,money(s.stray.gmv),cl.stray.length?"var(--orange)":"")}${kpi("TikTok Shop tự tạo",cl.auto.length,money(s.auto.gmv)+" · không tính cho team")}${kpi("Video cũ vẫn bán",cl.old.length,money(s.old.gmv))}</div>
  ${cl.stray.length?`<h3>Team đăng nhưng chưa có thẻ — cần tạo thẻ bù</h3>${tbl(["ID video","Mô tả","Ngày","Đơn","GMV"],cl.stray.slice(0,30).map(r=>`<tr><td class="mono">${r.id}</td><td>${esc(r.ten.slice(0,80))}</td><td>${r.tm}</td><td class="n">${r.don}</td><td class="n">${money(r.gmv)}</td></tr>`))}`:""}<p class="hint">Doanh thu dùng cột "GMV đến từ video", đơn dùng "Đơn hàng SKU đã ghi nhận" — khớp màn hình TikTok Shop cùng khoảng ngày.</p></section>`}
function adsSummary(res,S){const d=D();const rows=res?res.recs:d.adsRows;if(!rows.length)return "";const by=(f)=>{const g={};rows.forEach(r=>{const k=f(r)||"Chưa rõ";g[k]=g[k]||{chi:0,mua:0,gt:0,mess:0};g[k].chi+=r.chi;g[k].mua+=r.mua;g[k].gt+=r.gt;g[k].mess+=r.mess||0});return Object.entries(g).sort((a,b)=>b[1].chi-a[1].chi)};
  const T={chi:sum(rows,r=>r.chi),mua:sum(rows,r=>r.mua),gt:sum(rows,r=>r.gt)};const row=([k,v])=>`<tr><td><b>${esc(k)}</b></td><td class="n">${money(v.chi)}</td><td class="n">${nf(v.mua)}</td><td class="n">${money(v.gt)}</td><td class="n">${v.chi?(v.gt/v.chi).toFixed(1)+"×":"—"}</td><td class="n">${v.mua?money(v.chi/v.mua):"—"}</td></tr>`;
  const hd=["","Chi","Đơn","Doanh thu","ROAS","Chi phí / đơn"];
  return `<section class="card${res?" ok":""}"><div class="card-h"><h2>${res?"Đã nhập "+esc(res.name):"Ads Facebook tháng này"}</h2><span class="hint">${res?esc(res.range):"cộng các tuần đã nhập"}</span></div><div class="grid kpis">${kpi("Chi",money(T.chi))}${kpi("Đơn",nf(T.mua))}${kpi("Doanh thu",money(T.gt))}${kpi("ROAS",T.chi?(T.gt/T.chi).toFixed(1)+"×":"—")}</div>
  <div class="grid cols2"><div>${tbl(["Theo sản phẩm"].concat(hd.slice(1)),by(r=>({TT:"Tương tác",SI:"Tuyển sỉ"})[r.sku]||(r.sku?sk(r.sku).n:"")).map(row))}</div><div>${tbl(["Theo người chạy"].concat(hd.slice(1)),by(r=>r.nguoi).map(row))}</div></div>
  ${tbl(["Tuần","Chiến dịch","Người","Sản phẩm","Loại","Chi","Đơn","Doanh thu","Tin nhắn"],rows.map(r=>`<tr><td class="n">${r.tuan||""}</td><td class="mono">${esc(r.ten)}</td><td>${esc(r.nguoi||"?")}</td><td>${r.sku?(({TT:"Tương tác",SI:"Tuyển sỉ"})[r.sku]||sk(r.sku).n):`<span class="t-red">chưa rõ</span>`}</td><td>${esc(r.loai)}</td><td class="n">${money(r.chi)}</td><td class="n">${nf(r.mua)}</td><td class="n">${money(r.gt)}</td><td class="n">${nf(r.mess)}</td></tr>`))}</section>`}

