function pNhanSu(m){
  const U=D().users;
  m.innerHTML=H("Nhân sự & phân quyền")+`<section class="card">${tbl(["Tên đăng nhập","Họ tên","Chức danh","Vai trò","Đang làm","Số quyền",""],U.map(u=>`<tr><td class="mono">${u.username}</td><td><b>${esc(u.name)}</b></td><td>${esc(u.title)}</td><td>${u.id===ME.id?ROLES[u.role]:`<select data-ur="${u.id}">${opt(Object.entries(ROLES),u.role)}</select>`}</td><td>${u.id===ME.id?"Có":`<label class="sw-t"><input type="checkbox" data-ua="${u.id}" ${u.active?"checked":""}> ${u.active?"Có":"Đã khóa"}</label>`}</td><td class="n">${u.perms.length}/${ALL_PERMS.length}</td><td><button class="btn sm" data-pp="${u.id}">Phân quyền</button> <button class="btn sm" data-rp="${u.id}">Đặt lại mật khẩu</button></td></tr>`))}</section>
  <section class="card"><div class="card-h"><h2>Thêm nhân sự</h2></div><form class="frm row7" id="uf"><label class="field">Tên đăng nhập<input id="u-un" required pattern="[a-z0-9._]+" title="chữ thường, số, dấu chấm"></label><label class="field">Họ tên<input id="u-n" required></label><label class="field">Chức danh<input id="u-t"></label><label class="field">Vai trò<select id="u-r">${opt(Object.entries(ROLES).filter(([k])=>k!=="admin"),"content")}</select></label><label class="field">Mật khẩu ban đầu<input id="u-p" required minlength="6"></label><button class="btn pri">Thêm</button></form></section>`;
  m.querySelectorAll("[data-ur]").forEach(s=>s.onchange=()=>{DB.mutate(ME.name,`đổi vai trò ${userName(s.dataset.ur)} → ${ROLES[s.value]}`,d=>{const u=d.users.find(x=>x.id===s.dataset.ur);u.role=s.value;u.perms=ROLE_PRESET[s.value].slice()});toast("Đã đổi vai trò và áp quyền mặc định");renderMain()});
  m.querySelectorAll("[data-ua]").forEach(s=>s.onchange=()=>{DB.mutate(ME.name,(s.checked?"mở":"khóa")+" tài khoản "+userName(s.dataset.ua),d=>d.users.find(x=>x.id===s.dataset.ua).active=s.checked);renderMain()});
  m.querySelectorAll("[data-rp]").forEach(b=>b.onclick=()=>{const u=userBy(b.dataset.rp);$("#drawerIn").innerHTML=`<div class="dh"><h2>Đặt lại mật khẩu: ${esc(u.name)}</h2><button class="btn sm" id="dx">Đóng</button></div><form class="frm" id="rpf"><label class="field">Mật khẩu mới (≥6 ký tự)<input id="rp-p" required minlength="6"></label><button class="btn pri big">Lưu</button></form>`;$("#drawer").hidden=false;$("#dx").onclick=closeDrawer;$("#rpf").onsubmit=async e=>{e.preventDefault();const h=await hashPw(u.username,$("#rp-p").value);DB.mutate(ME.name,"đặt lại mật khẩu "+u.name,d=>d.users.find(x=>x.id===u.id).pw=h);closeDrawer();toast("Đã đặt lại mật khẩu")}});
  m.querySelectorAll("[data-pp]").forEach(b=>b.onclick=()=>{const u=userBy(b.dataset.pp);$("#drawerIn").innerHTML=`<div class="dh"><h2>Phân quyền: ${esc(u.name)}</h2><button class="btn sm" id="dx">Đóng</button></div><p class="hint">Vai trò: ${ROLES[u.role]}. Tick để cấp quyền riêng cho người này.</p><form id="ppf">${PERMS.map(([g,ps])=>`<fieldset class="pg"><legend>${g}</legend>${ps.map(([k,l])=>`<label class="ck"><input type="checkbox" name="p" value="${k}" ${u.perms.includes(k)?"checked":""} ${u.role==="admin"?"disabled":""}> ${l}</label>`).join("")}</fieldset>`).join("")}<div class="acts">${u.role!=="admin"?`<button class="btn pri">Lưu quyền</button><button type="button" class="btn" id="ppd">Về mặc định theo vai trò</button>`:"<span class='hint'>Quản trị có mọi quyền.</span>"}</div></form>`;$("#drawer").hidden=false;$("#dx").onclick=closeDrawer;
    $("#ppf").onsubmit=e=>{e.preventDefault();const ps=[...$$("#ppf input[name=p]:checked")].map(x=>x.value);DB.mutate(ME.name,"phân quyền "+u.name,d=>d.users.find(x=>x.id===u.id).perms=ps);closeDrawer();toast("Đã lưu quyền");renderMain()};
    if($("#ppd"))$("#ppd").onclick=()=>{DB.mutate(ME.name,"đặt quyền mặc định "+u.name,d=>d.users.find(x=>x.id===u.id).perms=ROLE_PRESET[u.role].slice());closeDrawer();renderMain()}});
  $("#uf").onsubmit=async e=>{e.preventDefault();const un=$("#u-un").value.trim().toLowerCase();if(D().users.some(u=>u.username===un)){toast("Tên đăng nhập đã có");return}const h=await hashPw(un,$("#u-p").value);const r=$("#u-r").value;DB.mutate(ME.name,"thêm nhân sự "+$("#u-n").value,d=>d.users.push({id:uid("u_"),username:un,name:$("#u-n").value,role:r,title:$("#u-t").value,active:true,pw:h,perms:ROLE_PRESET[r].slice()}));toast("Đã thêm, gửi tên đăng nhập + mật khẩu cho nhân sự");renderMain()};
}
let QEDIT=false;
function pQuyChuan(m){
  const Q=D().quychuan,ed=can(ME,"quychuan.sua")&&QEDIT;const head=Q.rules[0]||["Nhóm","Quy tắc","Áp dụng tại","Ai nhập","Tự động","Ghi chú"];
  m.innerHTML=H("Quy chuẩn thiết lập & vận hành","Đọc từ tab QUY_CHUAN_THIET_LAP")+`<section class="card">${can(ME,"quychuan.sua")?`<div class="card-h"><span class="sp"></span><button class="btn sm" id="qe">${QEDIT?"Xong, khóa lại":"Sửa quy chuẩn"}</button></div>`:""}${tbl(head.concat(ed?[""]:[]),Q.rules.slice(1).map((r,i)=>`<tr>${r.map((c,j)=>`<td${j===1?' class="wide"':""}>${ed?`<textarea rows="${j===1?2:1}" data-qr="${i+1}" data-j="${j}">${esc(c)}</textarea>`:j===0?`<b>${esc(c)}</b>`:esc(c)}</td>`).join("")}${ed?`<td><button class="btn sm" data-qx="${i+1}">Xóa</button></td>`:""}</tr>`))}${ed?`<button class="btn" id="qa">+ Thêm quy tắc</button>`:""}</section>
  <section class="card"><div class="card-h"><h2>Danh mục chọn</h2><span class="hint">Các ô trạng thái trên app chỉ chọn trong danh sách này</span></div>${tbl(Q.lists[0]||[],Q.lists.slice(1).map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join("")}</tr>`))}</section>`;
  m.querySelectorAll("[data-qr]").forEach(t=>t.onchange=()=>DB.mutate(ME.name,"sửa quy chuẩn",d=>d.quychuan.rules[+t.dataset.qr][+t.dataset.j]=t.value));
  m.querySelectorAll("[data-qx]").forEach(b=>b.onclick=()=>{DB.mutate(ME.name,"xóa quy tắc",d=>d.quychuan.rules.splice(+b.dataset.qx,1));renderMain()});
  if($("#qe"))$("#qe").onclick=()=>{QEDIT=!QEDIT;renderMain()};
  if($("#qa"))$("#qa").onclick=()=>{DB.mutate(ME.name,"thêm quy tắc",d=>d.quychuan.rules.push(["Nhóm mới","Quy tắc","","","",""]));renderMain()};
}
function pCaiDat(m){
  const d=D(),s=d.settings;
  m.innerHTML=H("Cài đặt & sao lưu")+`<section class="card"><div class="card-h"><h2>Thông số tháng</h2></div><div class="frm row7"><label class="field">Hôm nay là ngày (demo)<input id="c-td" type="number" value="${s.today}"></label><label class="field">Số liệu có đến ngày<input id="c-cut" type="number" value="${s.cutoff}"></label><label class="field">Ngày làm trong tháng<input id="c-wd" type="number" value="${s.workDays}"></label><label class="field">Winner ≥ (đơn)<input id="c-wn" type="number" value="${s.winnerOrders}"></label><label class="field">Tiềm năng ≥ (đơn)<input id="c-pt" type="number" value="${s.potential}"></label><label class="field">Thưởng / winner (đ)<input id="c-wb" type="number" value="${s.winnerBonus}"></label></div><div class="frm row7">${s.adsBudget.map((v,i)=>`<label class="field">Ngân sách Ads tuần ${i+1} (triệu)<input data-ab="${i}" type="number" value="${v/1e6}"></label>`).join("")}</div><button class="btn pri" id="c-save">Lưu thông số</button></section>
  <section class="card"><div class="card-h"><h2>Sản phẩm</h2></div><p>Thêm, sửa sản phẩm ở <button class="btn sm" data-go="sanpham">Danh mục sản phẩm</button>. Chọn sản phẩm cho từng tháng ở Kế hoạch › Bước 2 hoặc Lịch content › Pillar & tuyến.</p></section>
  <section class="card"><div class="card-h"><h2>Dữ liệu</h2></div><p>Bản thật: dữ liệu lưu trên máy chủ, tự sao lưu ra Google Sheet chỉ-đọc mỗi tối. Bản demo: dữ liệu nằm trong trình duyệt này.</p><div class="acts"><button class="btn" id="ex-j">Tải bản sao lưu (.json)</button><button class="btn" id="ex-c">Xuất lịch content (.csv)</button><label class="btn">Khôi phục từ .json<input type="file" id="im-j" accept=".json" hidden></label><button class="btn danger" id="rs">Xóa hết, về dữ liệu mẫu</button></div><div id="rsm" class="hint"></div></section>`;
  const dl=(name,txt,type)=>{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([txt],{type}));a.download=name;document.body.appendChild(a);a.click();a.remove()};
  $("#c-save").onclick=()=>{DB.mutate(ME.name,"sửa thông số",dt=>{Object.assign(dt.settings,{today:+$("#c-td").value||dt.settings.today,cutoff:+$("#c-cut").value,workDays:+$("#c-wd").value||26,winnerOrders:+$("#c-wn").value||100,potential:+$("#c-pt").value||30,winnerBonus:+$("#c-wb").value||0});$$("[data-ab]").forEach(i=>dt.settings.adsBudget[+i.dataset.ab]=(+i.value||0)*1e6)});toast("Đã lưu");render()};
  m.querySelectorAll("[data-pr]").forEach(x=>x.onchange=()=>DB.mutate(ME.name,"sửa sản phẩm",dt=>{const p=dt.products[+x.dataset.pr];p[x.dataset.f]=x.dataset.f==="gia"?+x.value||0:x.value}));
  $("#ex-j").onclick=()=>dl("ailla-mkt-hub-"+new Date().toISOString().slice(0,10)+".json",JSON.stringify(d,null,1),"application/json");
  $("#ex-c").onclick=()=>{const cols=[["id","Mã"],["kenh","Kênh"],["day","Ngày"],["sku","SKU"],["nguon","Nguồn"],["maTuyen","Mã tuyến"],["tuyen","Tuyến content"],["dangVideo","Dạng video"],["yTuong","Ý tưởng"],["hookText","Hook text"],["noiDung","Nội dung chi tiết"],["nguoi","Người lên nội dung"],["linkVideo","Link video"],["duyet","Trạng thái duyệt"],["ceo","CEO check"],["dang","Trạng thái đăng"],["ngayDang","Ngày đăng thật"],["linkDang","Link đăng"],["view","View"],["click","Click"],["don","Đơn"],["tiktokId","ID video TikTok"],["gmv","GMV"]];
    const rows=[cols.map(c=>c[1]).join(",")].concat(d.cards.map(c=>cols.map(([k])=>{const v=k==="nguoi"?userName(c.nguoi):k==="sku"?sk(c.sku).n:k==="duyet"?sheetDuyet(c):k==="dang"?sheetDang(c):k==="day"||k==="ngayDang"?dd(c[k]):c[k];return '"'+String(v??"").replace(/"/g,'""')+'"'}).join(",")));dl("lich-content-thang-"+MONTH.mon+".csv","﻿"+rows.join("\n"),"text/csv")};
  $("#im-j").onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(x.version!==APP_VERSION)throw 0;DB.data=x;DB.save();toast("Đã khôi phục");render()}catch(err){toast("File sao lưu không đúng")}};r.readAsText(f)};
  $("#rs").onclick=()=>{$("#rsm").innerHTML=`Mọi thay đổi trên trình duyệt này sẽ mất. <button class="btn sm danger" id="rs2">Xác nhận xóa</button>`;$("#rs2").onclick=async()=>{await DB.reset();ME=D().users.find(u=>u.id===ME.id);toast("Đã về dữ liệu mẫu");render()}};
}
function pMatKhau(m){
  m.innerHTML=H("Đổi mật khẩu")+`<section class="card narrow"><form class="frm" id="pwf"><label class="field">Mật khẩu hiện tại<input type="password" id="pw0" required autocomplete="current-password"></label><label class="field">Mật khẩu mới (≥6 ký tự)<input type="password" id="pw1" required minlength="6" autocomplete="new-password"></label><label class="field">Nhập lại<input type="password" id="pw2" required autocomplete="new-password"></label><div id="pwe" class="err"></div><button class="btn pri big">Đổi mật khẩu</button></form></section>`;
  $("#pwf").onsubmit=async e=>{e.preventDefault();if(ME.pw!==await hashPw(ME.username,$("#pw0").value)){$("#pwe").textContent="Mật khẩu hiện tại không đúng.";return}if($("#pw1").value!==$("#pw2").value){$("#pwe").textContent="Hai lần nhập không khớp.";return}const h=await hashPw(ME.username,$("#pw1").value);DB.mutate(ME.name,"đổi mật khẩu",d=>d.users.find(u=>u.id===ME.id).pw=h);ME=userBy(ME.id);toast("Đã đổi mật khẩu");renderMain()};
}

/* =====================================================================
   12. NHÂN VIÊN: VIỆC CỦA TÔI · KẾT QUẢ CỦA TÔI
   ===================================================================== */
const myCards=()=>D().cards.filter(c=>c.nguoi===ME.id);
const myTodo=()=>myCards().filter(c=>["kb","quay","dang"].includes(c.step)||(c.step==="xong"&&(chOf(c.kenh).needId?!c.tiktokId:!c.linkDang)));
function pViecToi(m){
  const M=myCards(),late=M.filter(isLate),back=M.filter(c=>["kb","quay"].includes(c.step)&&(c.gopy||[]).length);
  const sec=(t,L,h)=>`<section class="card"><div class="card-h"><h2>${t}</h2>${pill(L.length)}</div>${h?`<div class="hint">${h}</div>`:""}<div class="ulist">${L.map(c=>{const nx=nextAct(c);return `<div class="ui" data-card="${c.id}" style="border-left-color:${sk(c.sku).c}"><div class="ui-m">${c.id} · ${chOf(c.kenh).short} · ${sk(c.sku).n} · đăng ${dd(c.day)}</div><b>${esc(c.hookText||c.yTuong)}</b><div class="ui-m">${stepPill(c)} ${(c.gopy||[]).length&&["kb","quay"].includes(c.step)?pill("bị trả lại","amb"):""} ${c.step==="xong"&&c.don?pill(c.don+" đơn · "+money(c.gmv),"grn"):""} ${nx&&canMove(ME,c)&&!["dkb","dvd"].includes(c.step)?`<span class="nx">→ ${nx[0]}</span>`:""}</div></div>`}).join("")||`<p class="empty">Không có.</p>`}</div></section>`;
  const todo=myTodo().sort((a,b)=>(isLate(b)-isLate(a))||((b.gopy||[]).length-(a.gopy||[]).length)||a.day-b.day);
  m.innerHTML=H("Việc của "+esc(ME.name),`Hôm nay ${dd(D().settings.today)}`)+`<div class="grid kpis">${kpi("Cần làm",todo.length)}${kpi("Trễ hạn",late.length,"",late.length?"var(--red)":"")}${kpi("Bị trả lại",back.length,"",back.length?"var(--orange)":"")}${kpi("Đã đăng tháng này",M.filter(c=>c.step==="xong").length)}</div>`+
   sec("Cần làm",todo,"Bấm thẻ để làm bước tiếp theo")+sec("Đang chờ người khác",M.filter(c=>["dkb","worker","dvd"].includes(c.step)),"Chờ duyệt hoặc Worker đang dựng")+sec("Đã đăng gần đây",M.filter(c=>c.step==="xong"&&(chOf(c.kenh).needId?c.tiktokId:c.linkDang)).sort((a,b)=>b.day-a.day).slice(0,8));
}
function pKetQuaToi(m){
  const s=D().settings,M=myCards(),P=M.filter(c=>c.step==="xong"),W=P.filter(c=>c.don>=s.winnerOrders);
  m.innerHTML=H("Kết quả của "+esc(ME.name),`Số đơn cập nhật khi nhập báo cáo TikTok (đến ${dd(s.cutoff)})`)+`<div class="grid kpis">${kpi("Được giao",M.length)}${kpi("Đã đăng",P.length)}${kpi("Trễ hạn",M.filter(isLate).length)}${kpi("Đơn từ video",nf(sum(P,c=>c.don)),money(sum(P,c=>c.gmv)))}${kpi("Video Winner",W.length,"≥"+s.winnerOrders+" đơn · thưởng tạm tính "+money(W.length*s.winnerBonus),"var(--green)")}</div>
  <section class="card">${tbl(["Video","Kênh","Ngày","View","Đơn","GMV"],P.filter(c=>c.don>0).sort((a,b)=>b.don-a.don).map(c=>`<tr data-card="${c.id}"><td>${esc(c.hookText||c.yTuong)}<small>${c.id}</small></td><td>${chOf(c.kenh).short}</td><td>${dd(c.day)}</td><td class="n">${nf(c.view)}</td><td class="n">${c.don}</td><td class="n">${money(c.gmv)}</td></tr>`))}</section>`;
}

/* =====================================================================
   THẺ CHI TIẾT (đủ cột như tab TIKTOK / FANPAGE_CHINH)
   ===================================================================== */
let OPENED=null;
function openCard(id,o={}){
  const c=D().cards.find(x=>x.id===id);if(!c)return;OPENED=id;const ch=chOf(c.kenh),ed=canEditCard(ME,c),ap=can(ME,"viec.duyet"),gi=can(ME,"viec.giao"),all=can(ME,"lich.sua_tat_ca");
  const nx=c.step==="xong"&&(ch.needId?!c.tiktokId:!c.linkDang)?["Lưu",""]:nextAct(c);
  const F=(k,l,type="text",opts,dis)=>{const v=c[k]??"";const d=dis!==undefined?dis:!ed;return `<label class="field${type==="area"?" full":""}">${l}${type==="area"?`<textarea data-cf="${k}" rows="3" ${d?"disabled":""}>${esc(v)}</textarea>`:type==="sel"?`<select data-cf="${k}" ${d?"disabled":""}>${opt(opts,v)}</select>`:`<input data-cf="${k}" type="${type}" value="${esc(v)}" ${d?"disabled":""}>`}</label>`};
  const tuyenOpts=[["",""]].concat(D().tuyen.filter(t=>t.kenh===c.kenh).map(t=>[t.ma,t.ma+" · "+t.tuyen+" · "+sk(t.sku).n]));
  $("#drawerIn").innerHTML=`<div class="dh"><div><span class="mono">${c.id}</span> ${stepPill(c)} ${pill(sheetDuyet(c),sheetDuyet(c)==="Đã duyệt"?"grn":"gry")} ${pill(sheetDang(c),sheetDang(c)==="Đã đăng"?"grn":"gry")}</div><button class="btn sm" id="dx">Đóng</button></div>
   <h2 class="dtitle">${esc(c.hookText||c.yTuong)}</h2>
   ${o.err?`<div class="err box">${esc(o.err)}</div>`:""}${(c.gopy||[]).length?`<div class="warn">${c.gopy.map(g=>`<div><b>${esc(g.who)}</b> (${esc(g.t)}): ${esc(g.note)}</div>`).join("")}</div>`:""}
   ${sk(c.sku).claim?`<div class="note">Lưu ý claim ${esc(sk(c.sku).n)}: ${esc(sk(c.sku).claim)}</div>`:""}
   <div class="fgrp"><h3>Kế hoạch</h3><div class="fg">${F("kenh","Tài khoản / kênh","sel",CHANNELS.map(x=>x.k),!all)}${F("day","Ngày đăng dự kiến","number",null,!all)}${F("sku","SKU","sel",skOpts(),!all)}${F("nguon","Nguồn","sel",LISTS.nguon,!all)}${F("maTuyen","Mã tuyến","sel",tuyenOpts,!all)}${F("tuyen","Tuyến content","sel",LISTS.tuyen.concat(LISTS.tuyen.includes(c.tuyen)?[]:[c.tuyen]),!all)}${F("uuTien","Ưu tiên","sel",LISTS.uutien)}${F("ct","Chiến thuật","sel",D().tactics.map(t=>[t.k,t.k+" · "+t.n]),!all)}${F("mucTieu","Mục tiêu")}</div></div>
   <div class="fgrp"><h3>Kịch bản & triển khai</h3><div class="fg">${ch.needId?F("dangVideo","Dạng video","sel",LISTS.dangVideo):F("dangVideo","Định dạng bài","sel",LISTS.fbFormat)}${F("yTuong","Ý tưởng")}${F("hookText","Hook text")}${F("noiDung",ch.needId?"Nội dung chi tiết (lời)":"Nội dung bài","area")}${ch.needId?F("canhQuay","Cảnh quay chính")+F("daoCu","Đạo cụ / bối cảnh"):F("briefHinh","Brief hình ảnh / video","area")}${F("caption","Caption","area")}<label class="field">Người lên nội dung<select data-cf="nguoi" ${gi?"":"disabled"}>${opt(userOpts("Chưa giao"),c.nguoi)}</select></label>${ch.needId?F("host","Host / người quay"):""}</div></div>
   <div class="fgrp"><h3>Sản xuất & duyệt</h3><div class="fg">${ch.needId?F("nguoiDung","Người dựng")+F("ngayQuay","Ngày quay"):""}${F("linkVideo",ch.needId?"Link video quay (Drive)":"Link video (bài video / reel)","url")}${ch.needId?`<label class="field">Video Worker dựng<input value="${esc(c.linkFinal||"")}" disabled></label>`:F("linkAnh","Link ảnh / thư mục ảnh","url")}<label class="field">CEO check (claim)<select data-cf="ceo" ${ap?"":"disabled"}>${opt(LISTS.ceo,c.ceo)}</select></label></div></div>
   <div class="fgrp"><h3>Đăng & kết quả</h3><div class="fg">${F("ngayDang","Ngày đăng thật","number")}${F("linkDang",ch.needId?"Link bài đăng TikTok":"Link bài đăng Fanpage","url")}${ch.needId?F("tiktokId","ID video TikTok (19 số)")+`<label class="field">View · Giữ chân · Click<input value="${nf(c.view)} · ${c.giuChan||0}% · ${nf(c.click)}" disabled></label><label class="field">Đơn · GMV<input value="${nf(c.don)} · ${money(c.gmv)}" disabled></label>`:F("ketQua","Kết quả")}</div></div>
   ${(()=>{const root=c.repostOf||c.id,fam=D().cards.filter(x=>x.id===root||x.repostOf===root);const used=fam.map(x=>x.kenh),free=CHANNELS.filter(k=>!used.includes(k.k));return `<div class="fgrp"><h3>Đăng trên các kênh</h3>${tbl(["Thẻ","Kênh","Trạng thái","Link đăng","Đơn"],fam.map(x=>`<tr data-card="${x.id}"><td class="mono">${x.id}${x.id===root?" (gốc)":""}</td><td>${x.kenh}</td><td>${stepPill(x)}</td><td>${x.linkDang?`<a href="${esc(x.linkDang)}" target="_blank" rel="noopener">mở</a>`:"—"}</td><td class="n">${x.don||"—"}</td></tr>`))}${stepIdx(c.step)>=stepIdx("dang")&&free.length&&(canEditCard(ME,c)||can(ME,"viec.giao"))?`<div class="frm row4" style="margin-top:10px"><label class="field">Đăng thêm lên kênh<select id="rp-k">${opt(free.map(k=>k.k),free[0].k)}</select></label><label class="field">Ngày đăng<input id="rp-d" type="number" min="1" max="31" value="${Math.min(31,D().settings.today+1)}"></label><label class="field">Người đăng<select id="rp-n">${opt(userOpts(),c.nguoi)}</select></label><button class="btn" id="rp-go" type="button">Tạo thẻ đăng kênh này</button></div><p class="hint">Mỗi kênh một thẻ riêng để ghi caption, link bài, ID và số đơn riêng. Thẻ mới vào thẳng bước Chờ đăng.</p>`:stepIdx(c.step)<stepIdx("dang")?`<p class="hint">Duyệt video xong mới đăng thêm kênh được.</p>`:""}</div>`})()}
   <div class="fgrp"><h3>Tệp đính kèm</h3><div class="files">${(c.files||[]).map(f=>`<div class="file"><button class="lnk" data-fo="${f.id}" data-fn="${esc(f.name)}">${esc(f.name)}</button><small>${Math.round(f.size/1024)} KB · ${esc(f.by)} · ${esc(f.at)}</small>${ed?`<button class="lnk danger" data-fd="${f.id}">xóa</button>`:""}</div>`).join("")||`<span class="hint">Chưa có tệp.</span>`}</div>${ed?`<input type="file" id="cf-up" multiple><span class="hint">Kịch bản, ảnh, file thiết kế… ≤10MB/tệp</span>`:""}</div>
   ${o.back||["dkb","dvd"].includes(c.step)&&ap?`<label class="field full">Góp ý khi trả lại<input id="gy" placeholder="Cần sửa gì"></label>`:""}
   <div class="dact">${ed||ap||gi?`<button class="btn" id="dsave">Lưu</button>`:""}${nx&&canMove(ME,c)&&c.step!=="cg"?`<button class="btn pri big" id="dnext">${nx[1]?nx[0]:"Lưu ID / link"}</button>`:""}${["dkb","dvd"].includes(c.step)&&ap?`<button class="btn" id="dback">Trả lại</button>`:""}${all?`<button class="btn danger" id="ddel">Xóa</button>`:""}</div>
   <details class="hist"><summary>Lịch sử thẻ</summary>${(c.history||[]).map(h=>`<div>${esc(h.t)} · ${esc(h.who)} → ${stepName(h.to)}</div>`).join("")||"<div>Chưa có.</div>"}</details>`;
  $("#drawer").hidden=false;$("#dx").onclick=closeDrawer;
  const collect=()=>{const v={};$$("#drawerIn [data-cf]").forEach(x=>{if(x.disabled)return;let val=x.value;if(["day","ngayDang"].includes(x.dataset.cf))val=val===""?"":Math.min(31,Math.max(1,+val||1));v[x.dataset.cf]=val});return v};
  const save=(v)=>DB.mutate(ME.name,"cập nhật "+id,d=>{const x=d.cards.find(y=>y.id===id);const was=x.nguoi;Object.assign(x,v);if(v.nguoi!==undefined&&v.nguoi!==was){if(v.nguoi&&x.step==="cg")x.step="kb";if(!v.nguoi)x.step="cg"}});
  if($("#dsave"))$("#dsave").onclick=()=>{save(collect());toast("Đã lưu");closeDrawer();renderMain()};
  if($("#dnext"))$("#dnext").onclick=()=>{const v=collect();if(!nx[1]){const e=checkMove(c,"xong",v);if(e){openCard(id,{err:e});return}save(v);closeDrawer();renderMain();toast("Đã lưu");return}const err=moveCard(ME,id,nx[1],v);if(err){save(v);openCard(id,{err});return}closeDrawer();renderMain();toast(id+" → "+stepName(nx[1]))};
  if($("#dback"))$("#dback").onclick=()=>{sendBack(ME,id,($("#gy")||{}).value);closeDrawer();renderMain()};
  if($("#ddel"))$("#ddel").onclick=()=>{$("#ddel").outerHTML=`<button class="btn danger" id="ddel2">Bấm lần nữa để xóa</button>`;$("#ddel2").onclick=()=>{DB.mutate(ME.name,"xóa thẻ "+id,d=>d.cards=d.cards.filter(y=>y.id!==id));closeDrawer();renderMain()}};
  if($("#cf-up"))$("#cf-up").onchange=async e=>{const fs=await saveFiles(e.target.files);if(fs.length){DB.mutate(ME.name,"đính kèm "+fs.length+" tệp vào "+id,d=>{const x=d.cards.find(y=>y.id===id);x.files=(x.files||[]).concat(fs)});openCard(id);toast("Đã đính kèm")}};
  $$("#drawerIn [data-fo]").forEach(b=>b.onclick=()=>openFile(b.dataset.fo,b.dataset.fn));
  $$("#drawerIn tr[data-card]").forEach(r=>r.onclick=()=>{if(r.dataset.card!==id)openCard(r.dataset.card)});
  if($("#rp-go"))$("#rp-go").onclick=()=>{const r=repostCard(ME,id,$("#rp-k").value,+$("#rp-d").value,$("#rp-n").value);if(!r||r.startsWith("Video")||r.startsWith("Không")){toast(r);return}toast("Đã tạo thẻ "+r+" ở "+$("#rp-k").value);renderMain();openCard(r)};
  $$("#drawerIn [data-fd]").forEach(b=>b.onclick=async()=>{await FILES.del(b.dataset.fd).catch(()=>{});DB.mutate(ME.name,"xóa tệp ở "+id,d=>{const x=d.cards.find(y=>y.id===id);x.files=x.files.filter(f=>f.id!==b.dataset.fd)});openCard(id)});
}
function closeDrawer(){$("#drawer").hidden=true;OPENED=null}

/* ---------------- KHỞI ĐỘNG ---------------- */
setTimeout(async function boot(){
  await DB.load();
  if(typeof SERVER==="undefined")try{let s=sessionStorage.getItem(SKEY);try{const L=JSON.parse(localStorage.getItem(SKEY)||"null");if(L&&L.id&&L.exp>Date.now()){s=L.id;localStorage.setItem(SKEY,JSON.stringify({id:L.id,exp:Date.now()+30*864e5}))}}catch(e2){}if(s){const u=D().users.find(x=>x.id===s&&x.active);if(u&&(APP_MODE!=="admin"||["admin","lead"].includes(u.role)))ME=u}PAGE=localStorage.getItem(SKEY+"_p")||""}catch(e){}
  $("#drawer").addEventListener("click",e=>{if(e.target.id==="drawer")closeDrawer()});
  document.addEventListener("keydown",e=>{if(e.key==="Escape")closeDrawer()});
  render();
},0);

/* =====================================================================
   DANH MỤC SẢN PHẨM (quản trị)
   ===================================================================== */
let SPF={nhom:"",edit:false,q:""};
function pSanPham(m){
  const d=D(),C=d.catalog||[],ed=can(ME,"sanpham.quanly")&&SPF.edit,inPlan=k=>prods().some(p=>p.k===k);
  const list=C.filter(c=>(!SPF.nhom||c.nhom===SPF.nhom)&&(!SPF.q||(c.k+" "+c.n).toLowerCase().includes(SPF.q.toLowerCase())));
  const inp=(i,f,v,cls="")=>`<input class="${cls}" data-cp="${i}" data-f="${f}" value="${esc(v??"")}">`;
  m.innerHTML=H("Danh mục sản phẩm",`${C.length} sản phẩm · ${C.filter(c=>c.active).length} đang bán · ${prods().length} trong kế hoạch tháng ${MONTH.mon}`)+`
  <div class="filters"><select id="sp-n">${opt([["","Mọi nhóm"]].concat(NHOMS),SPF.nhom)}</select><input id="sp-q" placeholder="Tìm mã, tên…" value="${esc(SPF.q)}" style="max-width:240px"><span class="sp"></span>${can(ME,"sanpham.quanly")?`<button class="btn" id="sp-e">${SPF.edit?"Xong, khóa lại":"✏️ Sửa danh mục"}</button>`:""}</div>
  <section class="card flush"><div class="tbl edit"><table><thead><tr><th>Mã</th><th>Tên sản phẩm</th><th>Nhóm</th><th>Màu</th><th class="n">Giá trị đơn TB (đ)</th><th>Mô tả (dùng cho research, kịch bản)</th><th>Vấn đề của khách</th><th>Lưu ý claim</th><th>Đang bán</th><th>Kế hoạch tháng ${MONTH.mon}</th></tr></thead><tbody>
  ${list.map(c=>{const i=C.indexOf(c);return ed?`<tr><td class="mono">${c.k}</td><td>${inp(i,"n",c.n)}</td><td><select data-cp="${i}" data-f="nhom">${opt(NHOMS,c.nhom)}</select></td><td><input type="color" data-cp="${i}" data-f="c" value="${esc(c.c)}" style="width:46px;padding:2px"></td><td class="n">${inp(i,"gia",c.gia,"num")}</td><td><textarea rows="2" data-cp="${i}" data-f="mo">${esc(c.mo)}</textarea></td><td><textarea rows="2" data-cp="${i}" data-f="pain">${esc(c.pain)}</textarea></td><td><textarea rows="2" data-cp="${i}" data-f="claim">${esc(c.claim)}</textarea></td><td><input type="checkbox" data-cp="${i}" data-f="active" ${c.active?"checked":""} style="width:auto"></td><td>${inPlan(c.k)?pill("Có","grn"):"—"}</td></tr>`
   :`<tr><td class="mono">${c.k}</td><td>${swatch(c.k)}<b>${esc(c.n)}</b></td><td>${esc(c.nhom)}</td><td><i class="sw" style="background:${c.c}"></i></td><td class="n">${c.gia?nf(c.gia):"—"}</td><td class="wide">${esc(c.mo)}</td><td>${esc(c.pain)||"—"}</td><td>${esc(c.claim)||"—"}</td><td>${c.active?pill("Đang bán","grn"):pill("Ngừng")}</td><td>${inPlan(c.k)?pill(prods().find(p=>p.k===c.k).huong,"pnk"):can(ME,"kehoach.sua")&&c.active?`<button class="btn sm" data-addk="${c.k}">＋ Thêm vào tháng ${MONTH.mon}</button>`:"—"}</td></tr>`}).join("")}</tbody></table></div></section>
  ${can(ME,"sanpham.quanly")?`<section class="card"><div class="card-h"><h2>Thêm sản phẩm mới vào danh mục</h2></div><form class="frm" id="spf"><div class="row4"><label class="field">Mã (viết tắt, không dấu)<input id="sp-k" required pattern="[A-Za-z0-9]+" maxlength="6" placeholder="VD: NRC"></label><label class="field grow">Tên sản phẩm<input id="sp-t" required></label><label class="field">Nhóm<select id="sp-g">${opt(NHOMS,"Vệ sinh nhà cửa")}</select></label></div><div class="row4"><label class="field">Giá trị đơn TB (đ)<input id="sp-p" type="number" min="0" value="0"></label><label class="field">Màu<input id="sp-c" type="color" value="#0e7c86" style="height:40px"></label><label class="field grow">Vấn đề của khách<input id="sp-pain"></label></div><label class="field">Mô tả<textarea id="sp-mo" rows="2"></textarea></label><label class="field">Lưu ý claim<input id="sp-cl"></label><button class="btn pri">Thêm vào danh mục</button></form></section>`:""}`;
  $("#sp-n").onchange=e=>{SPF.nhom=e.target.value;renderMain()};$("#sp-q").onchange=e=>{SPF.q=e.target.value;renderMain()};
  if($("#sp-e"))$("#sp-e").onclick=()=>{SPF.edit=!SPF.edit;renderMain()};
  m.querySelectorAll("[data-cp]").forEach(x=>x.onchange=()=>{const i=+x.dataset.cp,f=x.dataset.f;const v=f==="active"?x.checked:f==="gia"?+x.value||0:x.value;DB.mutate(ME.name,"sửa danh mục "+C[i].k,dt=>{const c=dt.catalog[i];c[f]=v;const p=dt.products.find(y=>y.k===c.k);if(p&&f in p)p[f]=v});toast("Đã lưu")});
  m.querySelectorAll("[data-addk]").forEach(b=>b.onclick=()=>{const c=C.find(x=>x.k===b.dataset.addk);const err=addPlanProduct(ME,c.k,"Test",c.kenh||"TikTok chính",0);if(err){toast(err);return}toast("Đã thêm "+c.n+" vào kế hoạch tháng. Đặt mục tiêu ở Kế hoạch › Bước 2, thêm tuyến ở Pillar & tuyến");renderMain()});
  if($("#spf"))$("#spf").onsubmit=e=>{e.preventDefault();const k=$("#sp-k").value.trim().toUpperCase();if(C.some(c=>c.k===k)||OTHER_PRODUCTS.some(c=>c.k===k)&&k!=="LS"&&k!=="XR"){toast("Mã đã có");return}DB.mutate(ME.name,"thêm sản phẩm "+$("#sp-t").value,dt=>dt.catalog.push({k,n:$("#sp-t").value,nhom:$("#sp-g").value,c:$("#sp-c").value,gia:+$("#sp-p").value||0,mo:$("#sp-mo").value,pain:$("#sp-pain").value,claim:$("#sp-cl").value,kenh:"TikTok chính",active:true}));toast("Đã thêm vào danh mục");renderMain()};
}
